UPDATE public.faqs
SET answer = replace(answer, 'atty.boyet@westwoodlaw.ph', 'westwoodlawfirm1@gmail.com')
WHERE answer LIKE '%atty.boyet@westwoodlaw.ph%';


-- ############################################################################
-- ## 13/29  20261010_inquiry_firm_notified.sql
-- ############################################################################
-- ============================================================================
-- 20261010 — Track whether the firm has been emailed about an inquiry
-- ============================================================================
-- Signed-out visitors' inquiries are emailed to the firm (edge function
-- notify-inquiry) and deliberately excluded from Client Intake; only inquiries
-- filed by a signed-in client stay in the queue.
--
-- firm_notified_at is the claim: the function atomically sets it on the row it
-- is about to email, so a double-click, a retry or two tabs cannot email the
-- same inquiry twice. If the provider rejects the message, the function
-- releases the claim so a retry can still deliver it.
--
-- Idempotent.
-- ============================================================================

ALTER TABLE public.inquiries
  ADD COLUMN IF NOT EXISTS firm_notified_at TIMESTAMPTZ;


-- ############################################################################
-- ## 14/29  20261011_inquiries_service_role_grant.sql
-- ############################################################################
-- ============================================================================
-- 20261011 — service_role access to inquiries (for notify-inquiry)
-- ============================================================================
-- The notify-inquiry edge function runs as service_role and claims an inquiry
-- with UPDATE ... RETURNING, then releases the claim if the email fails.
-- On live, public.inquiries never received the table-level privileges
-- service_role normally inherits from the project defaults, so the first real
-- call died with:
--
--   permission denied for table inquiries
--
-- the same class of live-only grant gap as 20261007 (content tables). Grant
-- the two privileges the function needs, explicitly:
--   * UPDATE for the firm_notified_at claim itself;
--   * SELECT for the RETURNING columns the claim reads back.
--
-- Nothing else changes: RLS policies for anon/authenticated are untouched, and
-- service_role still bypasses RLS (it is the server-side role).
--
-- Idempotent: GRANT is a no-op when the privilege already exists.
-- ============================================================================

GRANT SELECT, UPDATE ON public.inquiries TO service_role;


-- ############################################################################
-- ## 15/29  20261012_admin_view_only_documents.sql
-- ############################################################################
-- ============================================================================
-- 20261012 — Admins are view-only on documents
-- ============================================================================
-- Product decision (2026-10-05): an admin may see every document record and
-- open non-confidential files, but may not author documents. A document that
-- arrives at the front desk goes to the assigned lawyer, who files it.
--
-- Already true (20261001): an admin could never author a Confidential
-- document and could not change or delete one; every upload/open/delete is
-- audited. This migration removes the remaining non-confidential upload path —
-- for the table row AND for the storage object — so the rule is enforced in
-- the database, not only by hidden buttons.
--
-- Unchanged: admins still read metadata at every access level
-- (private.can_access_document) and open Confidential content only through
-- break-glass (private.can_read_document_content).
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. The role gate that documents_insert_allowed calls.
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION private.can_upload_document(p_matter_id UUID, p_access_level public.access_level)
RETURNS BOOLEAN LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF NOT private.user_can_access_matter(p_matter_id) THEN RETURN FALSE; END IF;
  RETURN CASE private.get_user_role()
    WHEN 'admin'  THEN FALSE                       -- view-only: admins never author documents
    WHEN 'lawyer' THEN private.is_matter_lawyer_team(p_matter_id)
                       AND p_access_level IN ('Client & Assigned Lawyer','Staff Shared','Lawyer Only','Confidential')
    WHEN 'client' THEN p_access_level = 'Client & Assigned Lawyer'
    ELSE FALSE END;
END $$;

REVOKE ALL ON FUNCTION private.can_upload_document(UUID, public.access_level) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION private.can_upload_document(UUID, public.access_level) TO authenticated;

-- ----------------------------------------------------------------------------
-- 2. Storage insert. The file is uploaded before its documents row exists, so
--    this policy cannot see the access level — but it can see the role. An
--    admin uploads nothing to the documents bucket; lawyers and clients are
--    unchanged (the table policy above still decides who may author what).
-- ----------------------------------------------------------------------------
DROP POLICY IF EXISTS documents_storage_insert ON storage.objects;
CREATE POLICY documents_storage_insert
ON storage.objects FOR INSERT TO authenticated
WITH CHECK (
  bucket_id = 'documents'
  AND (SELECT private.user_can_access_matter_path(name))
  AND NOT (SELECT private.is_admin())
);

-- ----------------------------------------------------------------------------
-- 3. Storage delete. The row policy has always been uploader-only
--    (documents_delete_policy), but this one let an admin delete any file.
--    An admin who deleted someone else's document therefore removed the FILE
--    while the row survived (the row DELETE matched nothing and exited 0) —
--    the document became permanently unopenable and the UI still said
--    "deleted". With admins view-only the two policies now agree.
-- ----------------------------------------------------------------------------
DROP POLICY IF EXISTS documents_storage_delete ON storage.objects;
CREATE POLICY documents_storage_delete
ON storage.objects FOR DELETE TO authenticated
USING (
  bucket_id = 'documents'
  AND owner_id = (SELECT auth.uid())::TEXT
);


-- ############################################################################
-- ## 16/29  20261013_seminar_registrations.sql
-- ############################################################################
-- ============================================================================
-- 20261013 — Seminar registrations get a real link + email send log
-- ============================================================================
-- Seminar registration was already recorded as an inquiry (subject
-- 'Seminar registration'), but the seminar itself lived only as free text in
-- the message body. That made "email everyone who registered for this
-- seminar" impossible: there was no way to group the rows.
--
-- This migration:
--   1. adds inquiries.seminar_id (TEXT → public.seminar_events, nullable),
--      backfills the rows that can be matched from their message text,
--   2. extends submit_inquiry with an optional p_seminar_id,
--   3. adds public.seminar_email_log so the admin UI can show when a seminar
--      was last emailed and how many sends failed.
--
-- submit_inquiry must be DROPPED and re-created, not CREATE OR REPLACE'd:
-- adding a parameter would leave both the 7-arg and 8-arg signatures in place,
-- and with every argument DEFAULTed a 7-argument call becomes ambiguous
-- (PostgREST answers PGRST203). Dropping the old signature first keeps the
-- 7-argument callers working through the new default.
--
-- Safe to re-run.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. The link itself
-- ----------------------------------------------------------------------------
ALTER TABLE public.inquiries
  ADD COLUMN IF NOT EXISTS seminar_id TEXT REFERENCES public.seminar_events(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS inquiries_seminar_id_idx ON public.inquiries (seminar_id);

-- ----------------------------------------------------------------------------
-- 2. Backfill existing registrations.
--    strpos, not LIKE: a seminar title may contain % or _ and those must not
--    act as wildcards. Only rows matching exactly one seminar are linked —
--    two titles that prefix each other must not pick a winner at random.
-- ----------------------------------------------------------------------------
UPDATE public.inquiries i
SET seminar_id = m.seminar_id
FROM (
  SELECT i2.id AS inquiry_id, min(s.id) AS seminar_id
  FROM public.inquiries i2
  JOIN public.seminar_events s
    ON strpos(i2.message, 'Seminar: ' || s.title) > 0
  WHERE i2.seminar_id IS NULL
    AND i2.subject = 'Seminar registration'
  GROUP BY i2.id
  HAVING count(*) = 1
) m
WHERE i.id = m.inquiry_id;

-- ----------------------------------------------------------------------------
-- 3. submit_inquiry gains p_seminar_id
-- ----------------------------------------------------------------------------
DROP FUNCTION IF EXISTS public.submit_inquiry(TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT);

CREATE OR REPLACE FUNCTION public.submit_inquiry(
  p_name          TEXT DEFAULT NULL,
  p_email         TEXT DEFAULT NULL,
  p_phone         TEXT DEFAULT NULL,
  p_practice_area TEXT DEFAULT NULL,
  p_method        TEXT DEFAULT NULL,
  p_message       TEXT DEFAULT NULL,
  p_subject       TEXT DEFAULT NULL,
  p_seminar_id    TEXT DEFAULT NULL
) RETURNS TEXT
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_number   TEXT;
  v_uid      UUID := (SELECT auth.uid());
  v_seminar  TEXT := NULLIF(btrim(COALESCE(p_seminar_id, '')), '');
BEGIN
  -- Validated here rather than only in the browser: this function is reachable
  -- by anyone, so it cannot assume the form ran. ERRCODE 22023 is what makes
  -- PostgREST return 400 with this message instead of a generic failure.
  IF btrim(COALESCE(p_name, '')) = '' THEN
    RAISE EXCEPTION 'Please enter your name' USING ERRCODE = '22023';
  END IF;
  IF btrim(COALESCE(p_email, '')) = ''
     OR p_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN
    RAISE EXCEPTION 'Please enter a valid email address' USING ERRCODE = '22023';
  END IF;
  IF btrim(COALESCE(p_message, '')) = '' THEN
    RAISE EXCEPTION 'Please tell us how we can help' USING ERRCODE = '22023';
  END IF;
  IF v_seminar IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.seminar_events s WHERE s.id = v_seminar) THEN
    RAISE EXCEPTION 'That seminar is no longer listed — please refresh the page and try again'
      USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.inquiries (
    name, email, phone, practice_area, preferred_contact_method,
    message, subject, status, client_id, seminar_id
  ) VALUES (
    btrim(p_name),
    btrim(p_email),
    NULLIF(btrim(COALESCE(p_phone, '')), ''),
    COALESCE(btrim(COALESCE(p_practice_area, '')), ''),
    COALESCE(NULLIF(btrim(COALESCE(p_method, '')), ''), 'Email'),
    p_message,
    COALESCE(NULLIF(btrim(COALESCE(p_subject, '')), ''), 'General inquiry'),
    'New',
    -- The visitor cannot choose who this is filed under; it is themselves, or
    -- nobody when they are signed out. Same rule as inquiries_insert_policy.
    -- (client_id only — inquiries has no user_id column on live.)
    v_uid,
    v_seminar
  )
  RETURNING inquiry_number INTO v_number;

  RETURN v_number;
END $$;

REVOKE ALL ON FUNCTION public.submit_inquiry(TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_inquiry(TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT)
  TO anon, authenticated;

-- ----------------------------------------------------------------------------
-- 4. Send log. One row per "email every registrant of this seminar" action.
--    Written by the send-seminar-email edge function (service role), read by
--    the admin UI. Deliberately no INSERT policy: the browser never writes it.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.seminar_email_log (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  seminar_id      TEXT NOT NULL REFERENCES public.seminar_events(id) ON DELETE CASCADE,
  sent_by         UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  subject         TEXT NOT NULL,
  recipient_count INT NOT NULL DEFAULT 0,
  sent_count      INT NOT NULL DEFAULT 0,
  failed_count    INT NOT NULL DEFAULT 0,
  failures        JSONB NOT NULL DEFAULT '[]'::JSONB,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS seminar_email_log_seminar_id_idx ON public.seminar_email_log (seminar_id);
CREATE INDEX IF NOT EXISTS seminar_email_log_sent_by_idx ON public.seminar_email_log (sent_by);

ALTER TABLE public.seminar_email_log ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS seminar_email_log_select_admin ON public.seminar_email_log;
CREATE POLICY seminar_email_log_select_admin
ON public.seminar_email_log FOR SELECT TO authenticated
USING ((SELECT private.is_admin()));

-- Explicit grants, not project defaults: the send log must be readable by an
-- admin and writable by nobody else. On a project whose default privileges
-- grant authenticated ALL on new tables (Supabase's own bootstrap does, and the
-- harness replicates it), omitting authenticated from the REVOKE would leave
-- INSERT/UPDATE/DELETE granted at the table level — RLS would still refuse the
-- writes, but the next policy mistake would then open the table. 20261007 was
-- the same lesson for the content tables.
REVOKE ALL ON public.seminar_email_log FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.seminar_email_log TO authenticated;
GRANT ALL ON public.seminar_email_log TO service_role;

-- ----------------------------------------------------------------------------
-- Verify (read-only)
-- ----------------------------------------------------------------------------
DO $$
DECLARE v_sig TEXT := 'public.submit_inquiry(text,text,text,text,text,text,text,text)';
BEGIN
  IF to_regprocedure(v_sig) IS NULL THEN
    RAISE WARNING 'submit_inquiry was NOT re-created — the public forms will fail';
  ELSIF NOT has_function_privilege('anon', v_sig, 'EXECUTE') THEN
    RAISE WARNING 'anon cannot execute submit_inquiry — the public forms will fail';
  ELSIF to_regclass('public.seminar_email_log') IS NULL THEN
    RAISE WARNING 'seminar_email_log was NOT created — the send log will be empty';
  ELSE
    RAISE NOTICE 'seminar registrations: link column, RPC and send log are installed';
  END IF;
END $$;


-- ############################################################################
-- ## 17/29  20261014_audit_log_browser_writes.sql
-- ############################################################################
-- ============================================================================
-- 20261014  Audit log writes from the browser
-- ============================================================================
-- Reported 2026-10-05, from the signed-in portal:
--
--   POST /rest/v1/audit_logs?select=*  ->  403
--   audit.ts:101  Error logging audit event
--
-- src/lib/services/audit.ts writes with .insert(...).select().single(), i.e.
-- PostgREST runs INSERT ... RETURNING. That single statement needs FOUR things,
-- and the live project is missing all of the ones the chain never supplied:
--
--   1. INSERT privilege for authenticated            (grant)
--   2. an INSERT policy whose WITH CHECK passes      (RLS)
--   3. SELECT privilege for the RETURNING clause     (grant)
--   4. a SELECT policy that can see the new row      (RLS)
--
-- Why live is missing them: the project was built from the ad-hoc
-- schema-production.sql, which enables RLS on audit_logs with SELECT policies
-- only and grants SELECT alone. The two files that add the INSERT path —
-- 20260916_create_audit_logs_table.sql (grants + policies) and
-- 20260918_fix_all_rls_policies.sql (policy rewrite) — are NOT part of the
-- apply chain and never reached the live project. This is the same class of
-- gap 20261007 fixed for the content tables.
--
-- End state, and why each policy looks the way it does:
--   * INSERT  — the browser writes rows attributed to itself (auth.uid()), or
--               unattributed (user_id NULL) for pre-auth events. 20261003's
--               stamp_audit_source trigger decides provenance separately, so
--               this policy does not try to.
--   * SELECT  — own rows, plus every row for an ACTIVE admin. The admin policy
--               goes through private.is_admin() rather than an inline role
--               subquery so a deactivated or soft-deleted account loses the
--               ability (the point of 20261003 §2).
--   * The legacy policy names from schema-production.sql and 20260916 are
--     dropped so the table has exactly one rule per action; leaving the old
--     admin policy in place would OR around the is_active check.
--
-- Safe to re-run: every statement is DROP IF EXISTS or idempotent.
-- ============================================================================


-- ----------------------------------------------------------------------------
-- 1. Grants
-- ----------------------------------------------------------------------------
-- PUBLIC and anon get nothing: the audit trail is staff-only. authenticated
-- gets exactly the two privileges the browser path uses, and nothing else —
-- the trail is append-only for users (no UPDATE, no DELETE, no TRUNCATE).
-- service_role gets the lot (it bypasses RLS but still needs the privilege).
REVOKE ALL ON public.audit_logs FROM PUBLIC, anon;
REVOKE UPDATE, DELETE, TRUNCATE ON public.audit_logs FROM authenticated;
GRANT SELECT, INSERT ON public.audit_logs TO authenticated;
GRANT ALL ON public.audit_logs TO service_role;


-- ----------------------------------------------------------------------------
-- 2. Retire the legacy policies
-- ----------------------------------------------------------------------------
-- From schema-production.sql (select own / select admin) and 20260916
-- (view own / admins view all / authenticated insert).
DROP POLICY IF EXISTS "Users can view own audit logs" ON public.audit_logs;
DROP POLICY IF EXISTS "Admins can view all audit logs" ON public.audit_logs;
DROP POLICY IF EXISTS "Authenticated users can insert audit logs" ON public.audit_logs;
DROP POLICY IF EXISTS audit_logs_select_own ON public.audit_logs;
DROP POLICY IF EXISTS audit_logs_select_admin ON public.audit_logs;


-- ----------------------------------------------------------------------------
-- 3. The policies the browser path needs
-- ----------------------------------------------------------------------------
-- INSERT: users log their own actions. user_id IS NULL is kept from 20260918
-- for the pre-auth events (failed logins etc.) the auth service records.
DROP POLICY IF EXISTS audit_logs_insert_policy ON public.audit_logs;
CREATE POLICY audit_logs_insert_policy ON public.audit_logs
FOR INSERT TO authenticated
WITH CHECK (user_id = (SELECT auth.uid()) OR user_id IS NULL);

-- SELECT: own rows — this is also what makes INSERT ... RETURNING visible to
-- the writer, so the .select().single() in audit.ts can read the row back.
DROP POLICY IF EXISTS audit_logs_select_policy ON public.audit_logs;
CREATE POLICY audit_logs_select_policy ON public.audit_logs
FOR SELECT TO authenticated
USING (user_id = (SELECT auth.uid()));

-- SELECT: an active admin sees the whole trail. The portal's account-history
-- screen relies on this (getMyAuditLogs does not filter by user for admins).
DROP POLICY IF EXISTS audit_logs_select_admin_policy ON public.audit_logs;
CREATE POLICY audit_logs_select_admin_policy ON public.audit_logs
FOR SELECT TO authenticated
USING ((SELECT private.is_admin()));


-- ============================================================================
-- Verification
-- ============================================================================
DO $$
DECLARE v_missing TEXT := '';
BEGIN
  IF NOT has_table_privilege('authenticated', 'public.audit_logs', 'INSERT') THEN
    v_missing := v_missing || ' authenticated-lacks-INSERT';
  END IF;
  IF NOT has_table_privilege('authenticated', 'public.audit_logs', 'SELECT') THEN
    v_missing := v_missing || ' authenticated-lacks-SELECT';
  END IF;
  IF has_table_privilege('anon', 'public.audit_logs', 'SELECT') THEN
    v_missing := v_missing || ' anon-can-read';
  END IF;
  IF has_table_privilege('authenticated', 'public.audit_logs', 'UPDATE')
     OR has_table_privilege('authenticated', 'public.audit_logs', 'DELETE') THEN
    v_missing := v_missing || ' authenticated-can-mutate';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies
                 WHERE schemaname = 'public' AND tablename = 'audit_logs'
                   AND policyname = 'audit_logs_insert_policy') THEN
    v_missing := v_missing || ' no-insert-policy';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies
                 WHERE schemaname = 'public' AND tablename = 'audit_logs'
                   AND policyname = 'audit_logs_select_policy') THEN
    v_missing := v_missing || ' no-select-policy';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies
                 WHERE schemaname = 'public' AND tablename = 'audit_logs'
                   AND policyname = 'audit_logs_select_admin_policy') THEN
    v_missing := v_missing || ' no-admin-select-policy';
  END IF;

  IF v_missing = '' THEN
    RAISE NOTICE 'audit_logs browser writes: OK (grants + 3 policies in place)';
  ELSE
    RAISE WARNING 'audit_logs browser writes: INCOMPLETE —%', v_missing;
  END IF;
END $$;

-- ============================================================================
-- Migration complete
-- ============================================================================


-- ############################################################################
-- ## 18/29  20261015_matter_notes_encryption.sql
-- ############################################################################
-- ============================================================================
-- 20261015  Encrypt matter messages at rest (Tier B)
-- ============================================================================
-- matter_notes.body held every lawyer <-> client message as plain text. This
-- migration encrypts it with a symmetric key kept in Supabase Vault, so a
-- stolen database dump or backup is unreadable without the key, while the firm
-- keeps lawful access and the existing notification behaviour is preserved.
--
-- Shape of the design:
--   * The key lives in Vault — never in this file, and never in a table that
--     ships with a dump. It is generated once, on the first apply.
--   * A BEFORE INSERT OR UPDATE trigger encrypts transparently, so the browser
--     still writes plain text into matter_notes and RLS stays the write gate.
--   * Reads go through public.matter_notes_thread, a SECURITY INVOKER view, so
--     the matter_notes SELECT policy remains the single source of row truth.
--     The view is read-only; writes stay on the base table.
--   * The key is unreachable by a client: private.matter_note_key() has its
--     EXECUTE revoked from PUBLIC, and clients are granted only
--     private.decrypt_matter_note(), which can decrypt ciphertext the caller
--     already obtained under RLS and never exposes the key.
--
-- Residual, accepted on purpose: private.on_matter_note_insert() still copies
-- the first 140 characters of a client-visible message into
-- public.notifications.message as plain text — that is the snippet the bell
-- shows. Notifications already have their own access rules, and encrypting them
-- too would break the realtime subscription (the browser cannot decrypt a
-- ciphertext pushed to it), so it is out of scope here.
--
-- Safe to re-run: the key is created only if absent, the backfill only touches
-- rows not yet encrypted, and every object is CREATE OR REPLACE or guarded by
-- IF NOT EXISTS.
-- ============================================================================


-- ----------------------------------------------------------------------------
-- 0. Preflight: Vault must be available
-- ----------------------------------------------------------------------------
-- Loud on purpose. Without Vault there is no key store, and a silent no-op
-- would leave the messages in plain text while the owner believes otherwise.
DO $$
BEGIN
  IF to_regclass('vault.decrypted_secrets') IS NULL THEN
    RAISE EXCEPTION
      'Supabase Vault is not enabled on this project. Enable the vault extension (Dashboard -> Database -> Extensions) and re-run this file.';
  END IF;
END $$;


-- ----------------------------------------------------------------------------
-- 1. The key (created once, never written down here)
-- ----------------------------------------------------------------------------
-- 32 random bytes, base64. gen_random_bytes is pgcrypto in the extensions
-- schema; it is schema-qualified because every function below pins
-- search_path = ''.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM vault.secrets WHERE name = 'matter_notes_key') THEN
    PERFORM vault.create_secret(
      encode(extensions.gen_random_bytes(32), 'base64'),
      'matter_notes_key',
      'Tier-B symmetric key for public.matter_notes.body');
  END IF;
END $$;


-- ----------------------------------------------------------------------------
-- 2. Key accessor (NOT callable by clients)
-- ----------------------------------------------------------------------------
-- SECURITY DEFINER so the Vault read happens as the owner. EXECUTE is revoked
-- from PUBLIC: authenticated already has USAGE on the private schema, so a
-- client that could call this would simply read the key.
CREATE OR REPLACE FUNCTION private.matter_note_key() RETURNS TEXT
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'matter_notes_key';
$$;

REVOKE ALL ON FUNCTION private.matter_note_key() FROM PUBLIC;


-- ----------------------------------------------------------------------------
-- 3. Decrypt wrapper (safe to grant to clients)
-- ----------------------------------------------------------------------------
-- The one decrypt path a signed-in user may call. It returns the plain text of
-- the ciphertext it is handed and never reveals the key, so it adds no
-- capability: a caller can only obtain the ciphertext of rows the matter_notes
-- SELECT policy already lets them read.
CREATE OR REPLACE FUNCTION private.decrypt_matter_note(p_body TEXT) RETURNS TEXT
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT CASE
           WHEN p_body IS NULL THEN NULL
           ELSE extensions.pgp_sym_decrypt(decode(p_body, 'base64'), private.matter_note_key())
         END;
$$;

REVOKE ALL ON FUNCTION private.decrypt_matter_note(TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION private.decrypt_matter_note(TEXT) TO authenticated, service_role;


-- ----------------------------------------------------------------------------
-- 4. Mark the column and swap the length constraint
-- ----------------------------------------------------------------------------
-- body_encrypted is the idempotency marker for the backfill below and lets the
-- read view tolerate a row that predates the trigger. New rows are always true.
ALTER TABLE public.matter_notes
  ADD COLUMN IF NOT EXISTS body_encrypted BOOLEAN NOT NULL DEFAULT FALSE;

-- The original constraint checked the PLAIN TEXT length
-- (char_length(btrim(body)) BETWEEN 1 AND 5000). After encryption `body` is
-- base64 ciphertext, which is longer, so that check would reject long messages.
-- Drop it by inspecting the catalog rather than by guessing its auto-generated
-- name, then validate the plain-text bound in the trigger where the plain text
-- still exists.
DO $$
DECLARE c RECORD;
BEGIN
  FOR c IN
    SELECT conname FROM pg_constraint
    WHERE conrelid = 'public.matter_notes'::regclass
      AND contype = 'c'
      AND pg_get_constraintdef(oid) ILIKE '%char_length%'
      AND pg_get_constraintdef(oid) ILIKE '%btrim%'
  LOOP
    EXECUTE format('ALTER TABLE public.matter_notes DROP CONSTRAINT %I', c.conname);
  END LOOP;
END $$;

-- A ciphertext cap, so a non-trigger write cannot store something absurd.
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = 'public.matter_notes'::regclass
      AND conname = 'matter_notes_body_ciphertext_check'
  ) THEN
    ALTER TABLE public.matter_notes
      ADD CONSTRAINT matter_notes_body_ciphertext_check
      CHECK (char_length(body) BETWEEN 1 AND 20000);
  END IF;
END $$;


-- ----------------------------------------------------------------------------
-- 5. Backfill existing plain-text rows (idempotent)
-- ----------------------------------------------------------------------------
-- Runs BEFORE the trigger exists, and only touches rows not yet encrypted, so a
-- second apply is a no-op. The marker, not the value, decides what is already
-- ciphertext — a plain-text message that happens to look like base64 cannot be
-- mistaken for one.
UPDATE public.matter_notes
   SET body = encode(extensions.pgp_sym_encrypt(body, private.matter_note_key()), 'base64'),
       body_encrypted = TRUE
 WHERE body_encrypted = FALSE;


-- ----------------------------------------------------------------------------
-- 6. Transparent encryption on write
-- ----------------------------------------------------------------------------
-- INSERT: the browser always sends plain text, so always encrypt.
-- UPDATE: only re-encrypt when the old value was already ciphertext AND the
--         body actually changed. The OLD.body_encrypted guard is what stops the
--         backfill's own UPDATE (and a re-apply) from double-encrypting.
CREATE OR REPLACE FUNCTION private.encrypt_matter_note() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF char_length(btrim(NEW.body)) NOT BETWEEN 1 AND 5000 THEN
      RAISE EXCEPTION 'A message must be between 1 and 5000 characters'
        USING ERRCODE = '22023';
    END IF;
    NEW.body := encode(extensions.pgp_sym_encrypt(NEW.body, private.matter_note_key()), 'base64');
    NEW.body_encrypted := TRUE;

  ELSIF TG_OP = 'UPDATE' AND OLD.body_encrypted AND NEW.body IS DISTINCT FROM OLD.body THEN
    IF char_length(btrim(NEW.body)) NOT BETWEEN 1 AND 5000 THEN
      RAISE EXCEPTION 'A message must be between 1 and 5000 characters'
        USING ERRCODE = '22023';
    END IF;
    NEW.body := encode(extensions.pgp_sym_encrypt(NEW.body, private.matter_note_key()), 'base64');
    NEW.body_encrypted := TRUE;
  END IF;

  RETURN NEW;
END $$;

REVOKE ALL ON FUNCTION private.encrypt_matter_note() FROM PUBLIC;

DROP TRIGGER IF EXISTS matter_notes_encrypt ON public.matter_notes;
CREATE TRIGGER matter_notes_encrypt
BEFORE INSERT OR UPDATE ON public.matter_notes
FOR EACH ROW EXECUTE FUNCTION private.encrypt_matter_note();


-- ----------------------------------------------------------------------------
-- 7. The notification trigger must read plain text
-- ----------------------------------------------------------------------------
-- 20261004's function verbatim, except that the three previews decrypt first:
-- by the time the AFTER trigger runs, NEW.body is ciphertext.
CREATE OR REPLACE FUNCTION private.on_matter_note_insert() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_client   UUID;
  v_assigned UUID;
  v_member   UUID;
  v_is_client_author BOOLEAN;
BEGIN
  SELECT m.client_id, m.lawyer_id INTO v_client, v_assigned
  FROM public.matters m WHERE m.id = NEW.matter_id;

  v_is_client_author := (NEW.author_id IS NOT DISTINCT FROM v_client);

  INSERT INTO public.matter_events(matter_id, event_type, title, actor_id, visible_to_client)
  VALUES (
    NEW.matter_id,
    'note',
    CASE
      WHEN v_is_client_author THEN 'Message from the client'
      WHEN NEW.visibility = 'client' THEN 'Update from your lawyer'
      ELSE 'Internal note added'
    END,
    NEW.author_id,
    NEW.visibility = 'client'
  );

  IF NEW.visibility = 'client' THEN
    IF v_is_client_author THEN
      PERFORM private.create_notification(
        v_assigned, 'New message from your client',
        left(private.decrypt_matter_note(NEW.body), 140), 'info', 'matters');

      FOR v_member IN
        SELECT mm.lawyer_id FROM public.matter_members mm
        WHERE mm.matter_id = NEW.matter_id
          AND mm.lawyer_id IS DISTINCT FROM v_assigned
      LOOP
        PERFORM private.create_notification(
          v_member, 'New message from a client',
          left(private.decrypt_matter_note(NEW.body), 140), 'info', 'matters');
      END LOOP;
    ELSE
      PERFORM private.create_notification(
        v_client, 'New update on your matter',
        left(private.decrypt_matter_note(NEW.body), 140), 'info', 'matters');
    END IF;
  END IF;

  RETURN NEW;
END $$;


-- ----------------------------------------------------------------------------
-- 8. The read path: a decrypting SECURITY INVOKER view
-- ----------------------------------------------------------------------------
-- security_invoker is mandatory. Without it the view runs as its owner (the
-- table owner) and bypasses RLS, leaking every note to every signed-in user.
-- With it, the matter_notes SELECT policy still decides which rows a caller
-- sees; the view only decrypts the body of rows they were already allowed to
-- read.
CREATE OR REPLACE VIEW public.matter_notes_thread
WITH (security_invoker = TRUE) AS
SELECT
  id, matter_id, author_id, visibility, created_at, updated_at,
  CASE WHEN body_encrypted THEN private.decrypt_matter_note(body) ELSE body END AS body
FROM public.matter_notes;

-- CREATE OR REPLACE cannot be relied on to change view options; set it outright.
ALTER VIEW public.matter_notes_thread SET (security_invoker = TRUE);

REVOKE ALL ON public.matter_notes_thread FROM PUBLIC, anon;
GRANT SELECT ON public.matter_notes_thread TO authenticated, service_role;


-- ----------------------------------------------------------------------------
-- 9. Report what is now in force
-- ----------------------------------------------------------------------------
DO $$
DECLARE
  v_key     BOOLEAN;
  v_view    BOOLEAN;
  v_leak    BOOLEAN;
  v_wrapper BOOLEAN;
BEGIN
  SELECT EXISTS (SELECT 1 FROM vault.secrets WHERE name = 'matter_notes_key') INTO v_key;

  SELECT EXISTS (
    SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relname = 'matter_notes_thread'
      AND EXISTS (SELECT 1 FROM unnest(COALESCE(c.reloptions, '{}'::text[])) o
                  WHERE o = 'security_invoker=true')
  ) INTO v_view;

  SELECT has_function_privilege('authenticated', 'private.matter_note_key()', 'EXECUTE') INTO v_leak;
  SELECT has_function_privilege('authenticated', 'private.decrypt_matter_note(text)', 'EXECUTE') INTO v_wrapper;

  RAISE NOTICE '--------------------------------------------------------------';
  RAISE NOTICE 'matter_notes_key present (want true)       : %', v_key;
  RAISE NOTICE 'matter_notes_thread is security_invoker    : %', v_view;
  RAISE NOTICE 'authenticated can read the key (want false): %', v_leak;
  RAISE NOTICE 'authenticated can decrypt (want true)      : %', v_wrapper;
  RAISE NOTICE '--------------------------------------------------------------';
END $$;


-- ############################################################################
-- ## 19/29  20261016_profile_pictures_and_temp_passwords.sql
-- ############################################################################
-- ============================================================================
-- PROFILE PICTURES + FORCED PASSWORD CHANGE
-- ============================================================================
-- Two features, one migration because the frontend ships them together:
--
--   1. A public `avatars` storage bucket so every account (admin, lawyer,
--      client) can have a square profile picture. `profiles.profile_image`
--      already exists (20260918_content_tables.sql) and the public pages
--      already render it, so nothing else is needed to display one.
--
--   2. `profiles.must_change_password`, the flag an admin-created staff
--      account carries until it replaces the temporary password it was
--      emailed. The edge function `admin-create-user` sets it; the portal
--      gates on it and clears it once the user picks a new password.
--
-- WHY A PUBLIC BUCKET. Lawyer photos appear on the public site, so the bucket
-- must serve anonymous GETs. A public bucket serves
-- /storage/v1/object/public/... without consulting RLS, so client and admin
-- avatars are equally reachable *by their URL*. That is accepted: object names
-- are random UUIDs under the owner's uid, there is deliberately NO SELECT
-- policy (so nothing can be listed/enumerated — the same reasoning as the
-- lawyer-photos listing fix in 20261005_security_advisor_fixes.sql), and a
-- changed picture deletes the previous object.
--
-- ORDERING: the frontend selects `must_change_password`, so this migration must
-- be applied (and the PostgREST schema cache reloaded) BEFORE the matching
-- frontend build deploys. Otherwise the select fails with 42703 and every
-- sign-in redirect-loops.

-- ----------------------------------------------------------------------------
-- 1. Forced-password-change flag
-- ----------------------------------------------------------------------------
-- Deliberately NOT added to private.guard_profile_update()'s blocked column
-- list: the user has to be able to clear their own flag after changing the
-- password, and blocking it would lock them out of the portal for good.
ALTER TABLE public.profiles
  ADD COLUMN IF NOT EXISTS must_change_password BOOLEAN NOT NULL DEFAULT false;

COMMENT ON COLUMN public.profiles.must_change_password IS
  'True while an admin-created account still uses the temporary password it was emailed. Cleared by the account owner after they set a new one.';

-- ----------------------------------------------------------------------------
-- 2. Storage bucket + policies
-- ----------------------------------------------------------------------------
-- 5 MB, images only. The browser downscales to a 512x512 WebP before upload,
-- so a real file is a few tens of KB; the cap only stops abuse.
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES (
  'avatars', 'avatars', TRUE, 5242880,
  ARRAY['image/png', 'image/jpeg', 'image/webp']
)
ON CONFLICT (id) DO UPDATE
SET public = TRUE,
    file_size_limit = EXCLUDED.file_size_limit,
    allowed_mime_types = EXCLUDED.allowed_mime_types;

-- Write: an authenticated user may only create objects under their own uid
-- prefix (`<uid>/<uuid>.webp`); admins may manage anyone's, matching the
-- profiles_admin_write_policy that lets an admin edit another user's row.
DROP POLICY IF EXISTS avatars_storage_insert ON storage.objects;
CREATE POLICY avatars_storage_insert
ON storage.objects FOR INSERT TO authenticated
WITH CHECK (
  bucket_id = 'avatars'
  AND (
    (SELECT private.is_admin())
    OR (storage.foldername(name))[1] = (SELECT auth.uid())::TEXT
  )
);

-- Overwrite: same rule, so a re-upload (upsert) cannot cross into another uid.
DROP POLICY IF EXISTS avatars_storage_update ON storage.objects;
CREATE POLICY avatars_storage_update
ON storage.objects FOR UPDATE TO authenticated
USING (
  bucket_id = 'avatars'
  AND (
    (SELECT private.is_admin())
    OR (storage.foldername(name))[1] = (SELECT auth.uid())::TEXT
  )
)
WITH CHECK (
  bucket_id = 'avatars'
  AND (
    (SELECT private.is_admin())
    OR (storage.foldername(name))[1] = (SELECT auth.uid())::TEXT
  )
);

-- Delete: the uploader (owner) or an admin. Used to drop the previous picture
-- when a new one replaces it, and by the "Remove photo" action.
DROP POLICY IF EXISTS avatars_storage_delete ON storage.objects;
CREATE POLICY avatars_storage_delete
ON storage.objects FOR DELETE TO authenticated
USING (
  bucket_id = 'avatars'
  AND (
    (SELECT private.is_admin())
    OR owner_id = (SELECT auth.uid())::TEXT
  )
);

-- There is intentionally NO SELECT policy: a public bucket already serves the
-- object by URL, and adding SELECT would re-enable list() enumeration.

-- ----------------------------------------------------------------------------
-- 3. Make the new column visible to PostgREST immediately
-- ----------------------------------------------------------------------------
-- Hosted Supabase watches DDL, but an explicit reload removes any doubt that
-- "migration applied" and "the API sees the column" are the same moment.
NOTIFY pgrst, 'reload schema';


-- ############################################################################
-- ## 20/29  20261017_notify_admins_new_inquiry.sql
-- ############################################################################
-- ============================================================================
-- 20261017  Notify admins when a registered client files an inquiry
-- ============================================================================
-- A signed-in client's inquiry is deliberately NOT emailed to the firm: the
-- notify-inquiry edge function only claims rows with client_id IS NULL, so a
-- registered client's inquiry landed silently in Client Intake and nobody was
-- told. This adds a bell notification for every active admin, the same way a
-- new document, matter update or appointment already notifies people.
--
-- Scope: registered clients only (client_id IS NOT NULL). A signed-out
-- visitor's inquiry is emailed to the firm by notify-inquiry and is not in
-- Client Intake, so it is left alone here — one channel per audience.
--
-- Safe to re-run.
-- ============================================================================

CREATE OR REPLACE FUNCTION private.notify_admins_new_inquiry()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_admin   UUID;
  v_who     TEXT;
  v_subject TEXT;
BEGIN
  -- Registered clients only. A signed-out visitor's inquiry (client_id IS NULL)
  -- reaches the firm by email (notify-inquiry) and never enters Client Intake.
  IF NEW.client_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_who := COALESCE(NULLIF(btrim(NEW.name), ''), 'A client');
  v_subject := NULLIF(btrim(NEW.subject), '');

  -- Every active admin. create_notification() skips the actor, so an admin who
  -- files their own inquiry is not notified about it.
  FOR v_admin IN
    SELECT p.id
    FROM public.profiles AS p
    WHERE p.role = 'admin'::public.user_role
      AND COALESCE(p.is_active, TRUE)
      AND p.deleted_at IS NULL
  LOOP
    PERFORM private.create_notification(
      v_admin,
      'New client inquiry',
      v_who || ' submitted ' || NEW.inquiry_number || COALESCE(' — ' || v_subject, ''),
      'info',
      'intake'
    );
  END LOOP;

  RETURN NEW;
END $$;

-- Only the trigger may call it (create_notification is likewise private).
REVOKE ALL ON FUNCTION private.notify_admins_new_inquiry() FROM PUBLIC;

DROP TRIGGER IF EXISTS inquiries_notify_admins ON public.inquiries;
CREATE TRIGGER inquiries_notify_admins
AFTER INSERT ON public.inquiries
FOR EACH ROW EXECUTE FUNCTION private.notify_admins_new_inquiry();


-- ----------------------------------------------------------------------------
-- Verify (read-only)
-- ----------------------------------------------------------------------------
DO $$
BEGIN
  IF to_regprocedure('private.notify_admins_new_inquiry()') IS NULL THEN
    RAISE WARNING 'notify_admins_new_inquiry() was NOT created — admins will not be told about client inquiries';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'inquiries_notify_admins') THEN
    RAISE WARNING 'inquiries_notify_admins trigger is missing — the function will never run';
  ELSE
    RAISE NOTICE 'admins are notified when a registered client files an inquiry';
  END IF;
END $$;


-- ############################################################################
-- ## 21/29  20261018_realtime_inquiries_messaging_consultations.sql
-- ############################################################################
-- ============================================================================
-- 20261018  Realtime inquiries, inquiry conversations, and consultation
--           scheduling
-- ============================================================================
-- One migration for the three features that share the same plumbing:
--
--   * Inquiries gain a structured `requested_lawyer_id` (the form used to fold
--     the lawyer's name into the message text) and a real assignment path. The
--     old `inquiries_select_staff` policy let every lawyer read every inquiry
--     in the firm; lawyers now see only inquiries assigned to them, admins
--     keep the full view, and a guard trigger stops a lawyer from editing
--     anything but the status of their own assigned inquiry.
--   * `public.inquiry_messages` is the per-inquiry conversation between the
--     client and the assigned lawyer. Bodies are encrypted at rest with the
--     same Tier-B design as matter messages (20261015): a Vault key, a
--     transparent BEFORE trigger, and a SECURITY INVOKER read view. Read
--     receipts are stamped through a guarded RPC; messages are immutable.
--   * `appointments` gains matter-less consultation requests (`matter_id`
--     becomes nullable, `inquiry_id` links the request to the inquiry the
--     client filed), a booking guard that validates date/time on the backend,
--     and a `rescheduled_at` stamp. The existing partial unique index
--     (lawyer_id, date, time) WHERE status IN ('Pending','Confirmed') remains
--     the database-level double-booking constraint.
--
-- Realtime: inquiries, inquiry_messages, appointments and matter_notes join
-- the supabase_realtime publication. Supabase Realtime applies each table's
-- SELECT policies to postgres_changes, so a subscriber only ever receives rows
-- their RLS already allows — no public channels, no broadcast.
--
-- Safe to re-run: every object is guarded, CREATE OR REPLACE, or DROP+CREATE.
-- ============================================================================


-- ----------------------------------------------------------------------------
-- 0. Helper: is this profile an active lawyer? (RLS-safe)
-- ----------------------------------------------------------------------------
-- Policies and the public RPC run as the caller, and a client cannot read
-- other people's profiles, so an inline EXISTS against profiles would silently
-- return false. The check lives in a SECURITY DEFINER helper, like
-- private.is_admin() and friends.
CREATE OR REPLACE FUNCTION private.is_active_lawyer(p_id UUID) RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = p_id
      AND p.role = 'lawyer'::public.user_role
      AND COALESCE(p.is_active, TRUE)
      AND p.deleted_at IS NULL
  );
$$;

REVOKE ALL ON FUNCTION private.is_active_lawyer(UUID) FROM PUBLIC;

-- Policies evaluate their predicates as the caller, so resolving this call
-- needs EXECUTE for authenticated — the same explicit grant private.is_admin()
-- and friends carry (20261003). Without it the appointments_insert policy below
-- fails with "permission denied for function" instead of a policy decision.
GRANT EXECUTE ON FUNCTION private.is_active_lawyer(UUID) TO authenticated;


-- ----------------------------------------------------------------------------
-- 1. Inquiries: a structured requested lawyer, and assignment-scoped access
-- ----------------------------------------------------------------------------
ALTER TABLE public.inquiries
  ADD COLUMN IF NOT EXISTS requested_lawyer_id UUID REFERENCES public.profiles(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS idx_inquiries_requested_lawyer
  ON public.inquiries (requested_lawyer_id);

-- SELECT: three rules, kept as three policies so each one states its audience.
--   * own     — the client who filed it (client_id, or the email they filed
--               with, which is what schema-production always had).
--   * admin   — the front desk sees everything.
--   * lawyer  — ONLY inquiries assigned to them. This replaces the old
--               is_lawyer_or_admin() staff policy.
DROP POLICY IF EXISTS inquiries_select_own ON public.inquiries;
DROP POLICY IF EXISTS inquiries_select_staff ON public.inquiries;
DROP POLICY IF EXISTS inquiries_select_policy ON public.inquiries;
DROP POLICY IF EXISTS inquiries_select_admin ON public.inquiries;
DROP POLICY IF EXISTS inquiries_select_assigned_lawyer ON public.inquiries;

CREATE POLICY inquiries_select_own ON public.inquiries
FOR SELECT TO authenticated
USING (
  client_id = (SELECT auth.uid())
  OR lower(email) = lower((SELECT p.email FROM public.profiles AS p WHERE p.id = (SELECT auth.uid())))
);

CREATE POLICY inquiries_select_admin ON public.inquiries
FOR SELECT TO authenticated
USING ((SELECT private.is_admin()));

CREATE POLICY inquiries_select_assigned_lawyer ON public.inquiries
FOR SELECT TO authenticated
USING (
  assigned_to = (SELECT auth.uid())
  AND (SELECT private.get_user_role()) = 'lawyer'::public.user_role
);

-- UPDATE: admins edit anything; the assigned lawyer may only advance the
-- status, and the guard trigger below enforces exactly that.
DROP POLICY IF EXISTS inquiries_update_admin ON public.inquiries;
DROP POLICY IF EXISTS inquiries_update_policy ON public.inquiries;
DROP POLICY IF EXISTS inquiries_update_authenticated ON public.inquiries;
DROP POLICY IF EXISTS inquiries_update_staff ON public.inquiries;
DROP POLICY IF EXISTS inquiries_update_assigned_lawyer ON public.inquiries;

CREATE POLICY inquiries_update_admin ON public.inquiries
FOR UPDATE TO authenticated
USING ((SELECT private.is_admin()))
WITH CHECK ((SELECT private.is_admin()));

CREATE POLICY inquiries_update_assigned_lawyer ON public.inquiries
FOR UPDATE TO authenticated
USING (
  assigned_to = (SELECT auth.uid())
  AND (SELECT private.get_user_role()) = 'lawyer'::public.user_role
)
WITH CHECK (
  assigned_to = (SELECT auth.uid())
  AND (SELECT private.get_user_role()) = 'lawyer'::public.user_role
);

-- The real gate for a lawyer's update: status only, and only the statuses a
-- lawyer owns. RLS decides which ROWS a lawyer may touch; this decides which
-- COLUMNS and which values.
CREATE OR REPLACE FUNCTION private.guard_inquiry_update() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF auth.uid() IS NULL OR private.is_admin() THEN
    RETURN NEW;
  END IF;

  IF OLD.assigned_to IS DISTINCT FROM (SELECT auth.uid()) THEN
    RAISE EXCEPTION 'Only the assigned lawyer can update an inquiry'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.inquiry_number  IS DISTINCT FROM OLD.inquiry_number
     OR NEW.name          IS DISTINCT FROM OLD.name
     OR NEW.email         IS DISTINCT FROM OLD.email
     OR NEW.phone         IS DISTINCT FROM OLD.phone
     OR NEW.practice_area IS DISTINCT FROM OLD.practice_area
     OR NEW.preferred_lawyer IS DISTINCT FROM OLD.preferred_lawyer
     OR NEW.subject       IS DISTINCT FROM OLD.subject
     OR NEW.message       IS DISTINCT FROM OLD.message
     OR NEW.client_id     IS DISTINCT FROM OLD.client_id
     OR NEW.assigned_to   IS DISTINCT FROM OLD.assigned_to
     OR NEW.requested_lawyer_id IS DISTINCT FROM OLD.requested_lawyer_id
     OR NEW.seminar_id    IS DISTINCT FROM OLD.seminar_id
     OR NEW.firm_notified_at IS DISTINCT FROM OLD.firm_notified_at
     OR NEW.preferred_contact_method IS DISTINCT FROM OLD.preferred_contact_method THEN
    RAISE EXCEPTION 'An inquiry''s details cannot be edited here — only its status'
      USING ERRCODE = '42501';
  END IF;

  IF NEW.status NOT IN ('Under Review'::public.inquiry_status,
                        'Contacted'::public.inquiry_status,
                        'Closed'::public.inquiry_status) THEN
    RAISE EXCEPTION 'That inquiry status is reserved for the front desk'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END $$;

REVOKE ALL ON FUNCTION private.guard_inquiry_update() FROM PUBLIC;

DROP TRIGGER IF EXISTS inquiries_guard_update ON public.inquiries;
CREATE TRIGGER inquiries_guard_update
BEFORE UPDATE ON public.inquiries
FOR EACH ROW EXECUTE FUNCTION private.guard_inquiry_update();


-- ----------------------------------------------------------------------------
-- 2. submit_inquiry gains p_lawyer_id
-- ----------------------------------------------------------------------------
-- The client's chosen lawyer becomes a real profile id, validated here (the
-- browser is not trusted to name a lawyer), stored on `requested_lawyer_id`,
-- and — for registered clients only — assigned straight away so the lawyer's
-- portal and bell light up without the front desk relaying anything. Signed
-- out visitors cannot attach a lawyer: their inquiry stays an anonymous lead
-- that reaches the firm by email (notify-inquiry), exactly as before.
DROP FUNCTION IF EXISTS public.submit_inquiry(TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT);

CREATE OR REPLACE FUNCTION public.submit_inquiry(
  p_name          TEXT DEFAULT NULL,
  p_email         TEXT DEFAULT NULL,
  p_phone         TEXT DEFAULT NULL,
  p_practice_area TEXT DEFAULT NULL,
  p_method        TEXT DEFAULT NULL,
  p_message       TEXT DEFAULT NULL,
  p_subject       TEXT DEFAULT NULL,
  p_seminar_id    TEXT DEFAULT NULL,
  p_lawyer_id     UUID DEFAULT NULL
) RETURNS TEXT
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_number   TEXT;
  v_uid      UUID := (SELECT auth.uid());
  v_seminar  TEXT := NULLIF(btrim(COALESCE(p_seminar_id, '')), '');
  v_lawyer   UUID := NULL;
BEGIN
  -- Validated here rather than only in the browser: this function is reachable
  -- by anyone, so it cannot assume the form ran. ERRCODE 22023 is what makes
  -- PostgREST return 400 with this message instead of a generic failure.
  IF btrim(COALESCE(p_name, '')) = '' THEN
    RAISE EXCEPTION 'Please enter your name' USING ERRCODE = '22023';
  END IF;
  IF btrim(COALESCE(p_email, '')) = ''
     OR p_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN
    RAISE EXCEPTION 'Please enter a valid email address' USING ERRCODE = '22023';
  END IF;
  IF btrim(COALESCE(p_message, '')) = '' THEN
    RAISE EXCEPTION 'Please tell us how we can help' USING ERRCODE = '22023';
  END IF;
  IF v_seminar IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM public.seminar_events s WHERE s.id = v_seminar) THEN
    RAISE EXCEPTION 'That seminar is no longer listed — please refresh the page and try again'
      USING ERRCODE = '22023';
  END IF;

  -- The requested lawyer must be a real, active lawyer profile.
  IF p_lawyer_id IS NOT NULL THEN
    IF private.is_active_lawyer(p_lawyer_id) THEN
      v_lawyer := p_lawyer_id;
    ELSE
      RAISE EXCEPTION 'That lawyer is not available — please refresh the page and try again'
        USING ERRCODE = '22023';
    END IF;
  END IF;

  INSERT INTO public.inquiries (
    name, email, phone, practice_area, preferred_contact_method,
    message, subject, status, client_id, seminar_id,
    requested_lawyer_id, assigned_to
  ) VALUES (
    btrim(p_name),
    btrim(p_email),
    NULLIF(btrim(COALESCE(p_phone, '')), ''),
    COALESCE(btrim(COALESCE(p_practice_area, '')), ''),
    COALESCE(NULLIF(btrim(COALESCE(p_method, '')), ''), 'Email'),
    p_message,
    COALESCE(NULLIF(btrim(COALESCE(p_subject, '')), ''), 'General inquiry'),
    'New',
    -- The visitor cannot choose who this is filed under; it is themselves, or
    -- nobody when they are signed out. Same rule as inquiries_insert_policy.
    -- (client_id only — inquiries has no user_id column on live.)
    v_uid,
    v_seminar,
    v_lawyer,
    -- Auto-assignment is for registered clients only: a signed-out visitor's
    -- inquiry is an anonymous lead that the firm reviews first.
    CASE WHEN v_uid IS NOT NULL THEN v_lawyer ELSE NULL END
  )
  RETURNING inquiry_number INTO v_number;

  RETURN v_number;
END $$;

REVOKE ALL ON FUNCTION public.submit_inquiry(TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.submit_inquiry(TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, UUID)
  TO anon, authenticated;


-- ----------------------------------------------------------------------------
-- 3. Notifications for inquiry assignment and status
-- ----------------------------------------------------------------------------
-- The bell already covers documents, matters, appointments and new client
-- inquiries. These two add the lawyer-facing assignment ping and the
-- client-facing status ping.
CREATE OR REPLACE FUNCTION private.notify_inquiry_assigned()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  IF NEW.client_id IS NULL OR NEW.assigned_to IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.assigned_to IS NOT DISTINCT FROM OLD.assigned_to THEN
    RETURN NEW;
  END IF;

  -- create_notification() skips the actor, so an admin assigning an inquiry to
  -- themselves is not notified about it.
  PERFORM private.create_notification(
    NEW.assigned_to,
    'New inquiry assigned to you',
    NEW.inquiry_number || COALESCE(' — ' || NULLIF(btrim(NEW.subject), ''), ''),
    'info',
    'inquiries'
  );

  RETURN NEW;
END $$;

REVOKE ALL ON FUNCTION private.notify_inquiry_assigned() FROM PUBLIC;

DROP TRIGGER IF EXISTS inquiries_notify_assigned ON public.inquiries;
CREATE TRIGGER inquiries_notify_assigned
AFTER INSERT OR UPDATE OF assigned_to ON public.inquiries
FOR EACH ROW EXECUTE FUNCTION private.notify_inquiry_assigned();

CREATE OR REPLACE FUNCTION private.notify_inquiry_status()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  IF NEW.client_id IS NULL OR NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  PERFORM private.create_notification(
    NEW.client_id,
    'Your inquiry is now ' || NEW.status::TEXT,
    NEW.inquiry_number || COALESCE(' — ' || NULLIF(btrim(NEW.subject), ''), '')
      || ' is now ' || NEW.status::TEXT || '.',
    CASE WHEN NEW.status = 'Closed' THEN 'success' ELSE 'info' END,
    'inquiries'
  );

  RETURN NEW;
END $$;

REVOKE ALL ON FUNCTION private.notify_inquiry_status() FROM PUBLIC;

DROP TRIGGER IF EXISTS inquiries_notify_status ON public.inquiries;
CREATE TRIGGER inquiries_notify_status
AFTER UPDATE OF status ON public.inquiries
FOR EACH ROW EXECUTE FUNCTION private.notify_inquiry_status();


-- ----------------------------------------------------------------------------
-- 4. inquiry_messages — the client <-> assigned-lawyer conversation
-- ----------------------------------------------------------------------------
-- Same Tier-B shape as 20261015: the browser writes plain text, the trigger
-- encrypts, reads go through a SECURITY INVOKER view. A separate Vault key so
-- the two message families can be rotated independently.
DO $$
BEGIN
  IF to_regclass('vault.decrypted_secrets') IS NULL THEN
    RAISE EXCEPTION
      'Supabase Vault is not enabled on this project. Enable the vault extension (Dashboard -> Database -> Extensions) and re-run this file.';
  END IF;
END $$;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM vault.secrets WHERE name = 'inquiry_messages_key') THEN
    PERFORM vault.create_secret(
      encode(extensions.gen_random_bytes(32), 'base64'),
      'inquiry_messages_key',
      'Tier-B symmetric key for public.inquiry_messages.body');
  END IF;
END $$;

CREATE OR REPLACE FUNCTION private.inquiry_message_key() RETURNS TEXT
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'inquiry_messages_key';
$$;

REVOKE ALL ON FUNCTION private.inquiry_message_key() FROM PUBLIC;

CREATE OR REPLACE FUNCTION private.decrypt_inquiry_message(p_body TEXT) RETURNS TEXT
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT CASE
           WHEN p_body IS NULL THEN NULL
           ELSE extensions.pgp_sym_decrypt(decode(p_body, 'base64'), private.inquiry_message_key())
         END;
$$;

REVOKE ALL ON FUNCTION private.decrypt_inquiry_message(TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION private.decrypt_inquiry_message(TEXT) TO authenticated, service_role;

CREATE TABLE IF NOT EXISTS public.inquiry_messages (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  inquiry_id     UUID NOT NULL REFERENCES public.inquiries(id) ON DELETE CASCADE,
  author_id      UUID NOT NULL REFERENCES public.profiles(id) ON DELETE RESTRICT,
  body           TEXT NOT NULL,
  body_encrypted BOOLEAN NOT NULL DEFAULT FALSE,
  -- Stamped by public.mark_inquiry_messages_read() when the other party opens
  -- the conversation; NULL means "not seen yet".
  read_at        TIMESTAMPTZ,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT inquiry_messages_body_ciphertext_check CHECK (char_length(body) BETWEEN 1 AND 20000)
);

CREATE INDEX IF NOT EXISTS idx_inquiry_messages_inquiry
  ON public.inquiry_messages (inquiry_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_inquiry_messages_author
  ON public.inquiry_messages (author_id);

CREATE OR REPLACE FUNCTION private.encrypt_inquiry_message() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF char_length(btrim(NEW.body)) NOT BETWEEN 1 AND 5000 THEN
      RAISE EXCEPTION 'A message must be between 1 and 5000 characters'
        USING ERRCODE = '22023';
    END IF;
    NEW.body := encode(extensions.pgp_sym_encrypt(NEW.body, private.inquiry_message_key()), 'base64');
    NEW.body_encrypted := TRUE;
  END IF;
  -- Messages are immutable: there is no UPDATE branch on purpose.

  RETURN NEW;
END $$;

REVOKE ALL ON FUNCTION private.encrypt_inquiry_message() FROM PUBLIC;

DROP TRIGGER IF EXISTS inquiry_messages_encrypt ON public.inquiry_messages;
CREATE TRIGGER inquiry_messages_encrypt
BEFORE INSERT ON public.inquiry_messages
FOR EACH ROW EXECUTE FUNCTION private.encrypt_inquiry_message();

-- Who may see / join a conversation. SECURITY DEFINER so the inquiries lookup
-- is not itself filtered by the caller's RLS (the helper IS the check).
CREATE OR REPLACE FUNCTION private.user_is_inquiry_participant(p_inquiry_id UUID) RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.inquiries i
    WHERE i.id = p_inquiry_id
      AND (i.client_id = (SELECT auth.uid()) OR i.assigned_to = (SELECT auth.uid()))
  );
$$;

REVOKE ALL ON FUNCTION private.user_is_inquiry_participant(UUID) FROM PUBLIC;
-- Same rule as is_active_lawyer above: the inquiry_messages policies call this
-- as the caller, so authenticated needs the explicit grant.
GRANT EXECUTE ON FUNCTION private.user_is_inquiry_participant(UUID) TO authenticated;

CREATE OR REPLACE FUNCTION private.user_can_access_inquiry(p_inquiry_id UUID) RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT private.user_is_inquiry_participant(p_inquiry_id) OR private.is_admin();
$$;

REVOKE ALL ON FUNCTION private.user_can_access_inquiry(UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION private.user_can_access_inquiry(UUID) TO authenticated;

ALTER TABLE public.inquiry_messages ENABLE ROW LEVEL SECURITY;

-- SELECT: the two participants, plus admins for oversight (they already see
-- every inquiry in Client Intake). No UPDATE/DELETE policies: messages are
-- immutable, and read receipts go through the guarded RPC below.
DROP POLICY IF EXISTS inquiry_messages_select ON public.inquiry_messages;
CREATE POLICY inquiry_messages_select ON public.inquiry_messages
FOR SELECT TO authenticated
USING (private.user_can_access_inquiry(inquiry_id));

DROP POLICY IF EXISTS inquiry_messages_insert ON public.inquiry_messages;
CREATE POLICY inquiry_messages_insert ON public.inquiry_messages
FOR INSERT TO authenticated
WITH CHECK (
  author_id = (SELECT auth.uid())
  AND private.user_is_inquiry_participant(inquiry_id)
);

-- Explicit grants, not project defaults: only authenticated may touch it, and
-- only read + append.
REVOKE ALL ON public.inquiry_messages FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT ON public.inquiry_messages TO authenticated;
GRANT SELECT ON public.inquiry_messages TO service_role;

-- Read path: decrypting SECURITY INVOKER view (see 20261015 for the rationale;
-- security_invoker is mandatory or the view bypasses RLS).
CREATE OR REPLACE VIEW public.inquiry_messages_thread
WITH (security_invoker = TRUE) AS
SELECT
  id, inquiry_id, author_id, read_at, created_at, updated_at,
  CASE WHEN body_encrypted THEN private.decrypt_inquiry_message(body) ELSE body END AS body
FROM public.inquiry_messages;

ALTER VIEW public.inquiry_messages_thread SET (security_invoker = TRUE);

REVOKE ALL ON public.inquiry_messages_thread FROM PUBLIC, anon;
GRANT SELECT ON public.inquiry_messages_thread TO authenticated, service_role;

-- Read receipts. Only a participant may stamp them, only for messages they did
-- not write, and only once (read_at IS NULL).
CREATE OR REPLACE FUNCTION public.mark_inquiry_messages_read(p_inquiry_id UUID)
RETURNS INTEGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_uid   UUID := (SELECT auth.uid());
  v_count INTEGER;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Sign in to read this conversation' USING ERRCODE = '42501';
  END IF;
  IF NOT private.user_is_inquiry_participant(p_inquiry_id) THEN
    RAISE EXCEPTION 'Not your conversation' USING ERRCODE = '42501';
  END IF;

  UPDATE public.inquiry_messages
     SET read_at = NOW()
   WHERE inquiry_id = p_inquiry_id
     AND read_at IS NULL
     AND author_id <> v_uid;

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END $$;

REVOKE ALL ON FUNCTION public.mark_inquiry_messages_read(UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.mark_inquiry_messages_read(UUID) TO authenticated;

-- Bell notification for the other party. Preview is capped at 140 chars, the
-- same residual 20261015 accepted for matter messages.
CREATE OR REPLACE FUNCTION private.on_inquiry_message_insert()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_client   UUID;
  v_assigned UUID;
  v_preview  TEXT;
BEGIN
  SELECT i.client_id, i.assigned_to INTO v_client, v_assigned
  FROM public.inquiries i WHERE i.id = NEW.inquiry_id;

  v_preview := left(private.decrypt_inquiry_message(NEW.body), 140);

  IF NEW.author_id IS NOT DISTINCT FROM v_client THEN
    -- From the client to the assigned lawyer (create_notification no-ops on a
    -- NULL recipient, which covers an unassigned inquiry).
    PERFORM private.create_notification(
      v_assigned, 'New message about an inquiry', v_preview, 'info', 'inquiries');
  ELSE
    PERFORM private.create_notification(
      v_client, 'New message from the firm', v_preview, 'info', 'inquiries');
  END IF;

  RETURN NEW;
END $$;

REVOKE ALL ON FUNCTION private.on_inquiry_message_insert() FROM PUBLIC;

DROP TRIGGER IF EXISTS inquiry_messages_notify ON public.inquiry_messages;
CREATE TRIGGER inquiry_messages_notify
AFTER INSERT ON public.inquiry_messages
FOR EACH ROW EXECUTE FUNCTION private.on_inquiry_message_insert();


-- ----------------------------------------------------------------------------
-- 5. Appointments: matter-less consultation requests + backend validation
-- ----------------------------------------------------------------------------
-- A consultation request from the public site has no matter yet, so matter_id
-- must become nullable. inquiry_id links the appointment back to the inquiry
-- the same booking filed, so Client Intake and the calendar tell one story.
ALTER TABLE public.appointments ALTER COLUMN matter_id DROP NOT NULL;

ALTER TABLE public.appointments
  ADD COLUMN IF NOT EXISTS inquiry_id UUID REFERENCES public.inquiries(id) ON DELETE SET NULL;

ALTER TABLE public.appointments
  ADD COLUMN IF NOT EXISTS rescheduled_at TIMESTAMPTZ;

CREATE INDEX IF NOT EXISTS idx_appointments_inquiry ON public.appointments (inquiry_id);

-- INSERT: admins, the matter's own client/lawyer (unchanged rule), and — new —
-- a client requesting a consultation with a real, active lawyer, without a
-- matter. Status must be 'Pending' and the client must be themselves.
DROP POLICY IF EXISTS appointments_insert ON public.appointments;
CREATE POLICY appointments_insert ON public.appointments
FOR INSERT TO authenticated
WITH CHECK (
  (SELECT private.is_admin())
  OR (client_id = (SELECT auth.uid()) AND status = 'Pending'
      AND (
        (matter_id IS NULL AND private.is_active_lawyer(lawyer_id))
        OR EXISTS (SELECT 1 FROM public.matters m
                   WHERE m.id = appointments.matter_id
                     AND m.client_id = (SELECT auth.uid())
                     AND m.lawyer_id = appointments.lawyer_id)
      ))
  OR (lawyer_id = (SELECT auth.uid())
      AND EXISTS (SELECT 1 FROM public.matters m
                  WHERE m.id = appointments.matter_id
                    AND m.lawyer_id = (SELECT auth.uid())
                    AND m.client_id = appointments.client_id))
);

-- Backend date/format validation + the reschedule stamp. The partial unique
-- index uq_appointments_lawyer_slot (20261001) already makes double-booking
-- impossible at the database level; this adds the checks a client-side
-- date-picker cannot be trusted to perform.
CREATE OR REPLACE FUNCTION private.guard_appointment_booking() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_slot_changed BOOLEAN;
BEGIN
  v_slot_changed := (TG_OP = 'INSERT')
                 OR NEW.date IS DISTINCT FROM OLD.date
                 OR NEW.time IS DISTINCT FROM OLD.time;

  IF TG_OP = 'UPDATE' AND v_slot_changed THEN
    NEW.rescheduled_at := NOW();
  END IF;

  IF NEW.status IN ('Pending'::public.appointment_status, 'Confirmed'::public.appointment_status)
     AND v_slot_changed THEN
    -- Two accepted shapes: 24-hour 'HH:MM' (what new callers should send) and
    -- the 12-hour 'H:MM AM/PM' the existing AppointmentsPanel has always
    -- booked with. Anything else — '25:99', free text — is refused. Both
    -- branches pin the hour and minute ranges, so '99:99 PM' cannot slip in.
    IF NEW.time !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
       AND NEW.time !~ '^(0?[1-9]|1[0-2]):[0-5][0-9] (AM|PM)$' THEN
      RAISE EXCEPTION 'Appointment time must be in HH:MM or H:MM AM/PM format'
        USING ERRCODE = '22023';
    END IF;
    IF NEW.date < CURRENT_DATE THEN
      RAISE EXCEPTION 'Appointments cannot be booked in the past' USING ERRCODE = '22023';
    END IF;
  END IF;

  RETURN NEW;
END $$;

REVOKE ALL ON FUNCTION private.guard_appointment_booking() FROM PUBLIC;

DROP TRIGGER IF EXISTS appointments_guard_booking ON public.appointments;
CREATE TRIGGER appointments_guard_booking
BEFORE INSERT OR UPDATE ON public.appointments
FOR EACH ROW EXECUTE FUNCTION private.guard_appointment_booking();

-- The notify trigger learns the reschedule branch and fires on date/time too.
CREATE OR REPLACE FUNCTION private.notify_appointment_changed()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_title TEXT;
  v_msg TEXT;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_title := 'New appointment scheduled';
    v_msg := NEW.appointment_type || ' on ' || NEW.date::TEXT || ' at ' || NEW.time || ' (' || NEW.mode::TEXT || ').';
  ELSIF NEW.status IS DISTINCT FROM OLD.status THEN
    v_title := 'Appointment ' || lower(NEW.status::TEXT);
    v_msg := NEW.appointment_type || ' on ' || NEW.date::TEXT || ' at ' || NEW.time || ' is now ' || NEW.status::TEXT || '.';
  ELSIF NEW.date IS DISTINCT FROM OLD.date OR NEW.time IS DISTINCT FROM OLD.time THEN
    v_title := 'Appointment rescheduled';
    v_msg := NEW.appointment_type || ' is now on ' || NEW.date::TEXT || ' at ' || NEW.time || '.';
  ELSE
    RETURN NEW;
  END IF;

  PERFORM private.create_notification(NEW.client_id, v_title, v_msg,
    CASE WHEN NEW.status = 'Cancelled' THEN 'warning' ELSE 'info' END, 'appointments');
  PERFORM private.create_notification(NEW.lawyer_id, v_title, v_msg,
    CASE WHEN NEW.status = 'Cancelled' THEN 'warning' ELSE 'info' END, 'appointments');

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS appointments_notify_changed ON public.appointments;
CREATE TRIGGER appointments_notify_changed
AFTER INSERT OR UPDATE OF status, date, time ON public.appointments
FOR EACH ROW EXECUTE FUNCTION private.notify_appointment_changed();


-- ----------------------------------------------------------------------------
-- 6. Realtime: publish the tables the portal subscribes to
-- ----------------------------------------------------------------------------
-- Supabase Realtime applies each table's SELECT policies to postgres_changes,
-- so clients and lawyers only receive their own rows. REPLICA IDENTITY stays
-- default: the app refetches on any event and never needs old-row values.
DO $$
DECLARE
  t TEXT;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    RAISE NOTICE 'supabase_realtime publication not found — skipping realtime registration';
    RETURN;
  END IF;

  FOREACH t IN ARRAY ARRAY['inquiries', 'inquiry_messages', 'appointments', 'matter_notes'] LOOP
    IF NOT EXISTS (
      SELECT 1 FROM pg_publication_tables
      WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = t
    ) THEN
      EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', t);
    END IF;
  END LOOP;
END $$;


-- ----------------------------------------------------------------------------
-- 7. Grants for the notify-event edge function (service role)
-- ----------------------------------------------------------------------------
-- The email function resolves recipients from trusted records with the service
-- role. inquiries is already granted (20261011); profiles and appointments
-- were not, and a missing grant fails as 42501 at send time.
GRANT SELECT ON public.profiles TO service_role;
GRANT SELECT ON public.appointments TO service_role;


-- ----------------------------------------------------------------------------
-- 8. Verify (read-only)
-- ----------------------------------------------------------------------------
DO $$
DECLARE
  v_col    BOOLEAN;
  v_table  BOOLEAN;
  v_view   BOOLEAN;
  v_key    BOOLEAN;
  v_pols   INTEGER;
  v_pub    INTEGER;
BEGIN
  SELECT EXISTS (SELECT 1 FROM information_schema.columns
                 WHERE table_schema = 'public' AND table_name = 'inquiries'
                   AND column_name = 'requested_lawyer_id') INTO v_col;
  SELECT to_regclass('public.inquiry_messages') IS NOT NULL INTO v_table;
  SELECT EXISTS (
    SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relname = 'inquiry_messages_thread'
      AND EXISTS (SELECT 1 FROM unnest(COALESCE(c.reloptions, '{}'::text[])) o
                  WHERE o = 'security_invoker=true')
  ) INTO v_view;
  SELECT EXISTS (SELECT 1 FROM vault.secrets WHERE name = 'inquiry_messages_key') INTO v_key;
  SELECT count(*) FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'inquiry_messages' INTO v_pols;
  SELECT count(*) FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime' AND schemaname = 'public'
      AND tablename IN ('inquiries', 'inquiry_messages', 'appointments', 'matter_notes') INTO v_pub;

  RAISE NOTICE '--------------------------------------------------------------';
  RAISE NOTICE 'inquiries.requested_lawyer_id present (want true) : %', v_col;
  RAISE NOTICE 'inquiry_messages table present (want true)       : %', v_table;
  RAISE NOTICE 'thread view is security_invoker (want true)      : %', v_view;
  RAISE NOTICE 'inquiry_messages_key present (want true)         : %', v_key;
  RAISE NOTICE 'inquiry_messages policies (want 2)               : %', v_pols;
  RAISE NOTICE 'realtime tables registered (want 4)              : %', v_pub;
  RAISE NOTICE '--------------------------------------------------------------';
END $$;


-- ############################################################################
-- ## 22/29  20261019_notify_event_email_log.sql
-- ############################################################################
-- ============================================================================
-- 20261019  Email claim log for the notify-event edge function
-- ============================================================================
-- Transactional email for registered users — inquiry confirmation,
-- consultation request, appointment status changes, new inquiry message —
-- goes through the notify-event edge function. That function resolves every
-- recipient from the database with the service role, and needs each email to
-- go out at most once even when a browser retries or two tabs race.
--
-- The claim is an INSERT with ON CONFLICT DO NOTHING: only the request whose
-- insert actually created the row sends the email. The unique key is
-- (event, entity_id, recipient) — one email per event per record per person.
--
-- Nobody but the service role can touch this table: RLS is on with no
-- policies, and the table grants are revoked from every other role. It stores
-- ids, recipient emails and an event name — never message content.
--
-- Safe to re-run: guarded CREATEs only.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.email_events (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  -- 'inquiry_submitted' | 'consultation_requested' | 'appointment_status' | 'inquiry_message'
  event      TEXT NOT NULL,
  entity_id  UUID NOT NULL,
  recipient  TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT email_events_once UNIQUE (event, entity_id, recipient)
);

CREATE INDEX IF NOT EXISTS idx_email_events_entity ON public.email_events (entity_id);

ALTER TABLE public.email_events ENABLE ROW LEVEL SECURITY;

-- service_role bypasses RLS and is the only role with a grant; anon and
-- authenticated see nothing even if they guess the table name.
REVOKE ALL ON public.email_events FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT ON public.email_events TO service_role;


-- ----------------------------------------------------------------------------
-- Verify (read-only)
-- ----------------------------------------------------------------------------
DO $$
DECLARE
  v_rls   BOOLEAN;
  v_uniq  BOOLEAN;
  v_anon  BOOLEAN;
  v_svc   BOOLEAN;
BEGIN
  SELECT relrowsecurity INTO v_rls FROM pg_class WHERE oid = 'public.email_events'::regclass;
  SELECT EXISTS (SELECT 1 FROM pg_constraint
                 WHERE conrelid = 'public.email_events'::regclass
                   AND conname = 'email_events_once') INTO v_uniq;
  SELECT has_table_privilege('anon', 'public.email_events', 'SELECT') INTO v_anon;
  SELECT has_table_privilege('service_role', 'public.email_events', 'INSERT') INTO v_svc;

  RAISE NOTICE '--------------------------------------------------------------';
  RAISE NOTICE 'email_events RLS enabled (want true)      : %', v_rls;
  RAISE NOTICE 'one-email-per-recipient constraint (want true) : %', v_uniq;
  RAISE NOTICE 'anon can read email_events (want false)   : %', v_anon;
  RAISE NOTICE 'service_role can insert claims (want true): %', v_svc;
  RAISE NOTICE '--------------------------------------------------------------';
END $$;


-- ############################################################################
-- ## 23/29  20261020_realtime_remaining_tables.sql
-- ############################################################################
-- ============================================================================
-- 20261020 — Realtime for every remaining portal surface
-- ============================================================================
-- 20260929 published `notifications`; 20261018 published `inquiries`,
-- `inquiry_messages`, `appointments` and `matter_notes`. Every other table the
-- portal or the public site renders still required a manual reload before a
-- change appeared: matters, documents, matter activity, the matter team,
-- profiles (names and pictures), audit logs, the content tables and the
-- seminar send log.
--
-- This migration publishes the rest so one refetch-on-event subscription per
-- screen keeps those surfaces live. It adds no tables, columns or policies —
-- each table's existing SELECT policies remain the security boundary.
--
-- Realtime semantics this relies on (Supabase docs, "Postgres Changes"):
--   * a table only streams when it is in the `supabase_realtime` publication;
--   * INSERT and UPDATE events are authorized against each subscriber's RLS —
--     a subscriber can never receive a row their SELECT policy would hide, and
--     an UPDATE that moves a row out of someone's visibility is dropped for
--     them (their next refetch is authoritative);
--   * DELETE events are NOT RLS-filtered (there is no row left to authorize)
--     and carry only the primary key — the app never renders from `payload`,
--     it refetches, so a delete event can never leak row contents;
--   * a *filtered* subscription only receives DELETE events when the table has
--     REPLICA IDENTITY FULL, so the three tables whose deletes happen in the
--     UI and are subscribed with a filter get it below (documents,
--     matter_members, notifications). The rest keep the default identity —
--     their deletes either never happen or are subscribed unfiltered.
--
-- Delivery is best-effort by design: the frontend treats every event as
-- "something changed, refetch", sharing one merge path with the initial load.
-- A dropped event is a stale row until the next signal, never a duplicate and
-- never a broken screen.

-- ----------------------------------------------------------------------------
-- 1. Replica identity for the tables whose filtered DELETE events matter
-- ----------------------------------------------------------------------------
-- documents      — a deleted document must leave every open documents list;
--                  MatterDetail subscribes with `matter_id=eq.<id>`.
-- matter_members — removing a lawyer from the team must update the open modal.
-- notifications  — useNotifications subscribes with `user_id=eq.<id>` and
--                  drops the row on DELETE (payload.old carries the PK).
ALTER TABLE IF EXISTS public.documents REPLICA IDENTITY FULL;
ALTER TABLE IF EXISTS public.matter_members REPLICA IDENTITY FULL;
ALTER TABLE IF EXISTS public.notifications REPLICA IDENTITY FULL;

-- ----------------------------------------------------------------------------
-- 2. Publish the remaining tables
-- ----------------------------------------------------------------------------
DO $$
DECLARE
  t TEXT;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    RAISE NOTICE 'supabase_realtime publication not found — skipping realtime registration';
    RETURN;
  END IF;

  FOREACH t IN ARRAY ARRAY[
    'profiles',             -- names + pictures (own row; all rows for staff)
    'matters',              -- matter lists and dashboard counters
    'documents',            -- document lists and per-matter panels
    'matter_events',        -- client dashboard activity + matter timeline
    'matter_members',       -- matter team panel
    'audit_logs',           -- admin audit tab
    'practice_areas',       -- portal + public content
    'specialists',          -- partner network (portal + public)
    'corporate_clients',    -- public about/contact pages
    'articles',             -- insights (public + content manager)
    'faqs',                 -- FAQ tab (public + content manager)
    'seminar_events',       -- seminars (public + content manager)
    'retainer_packages',    -- retainers (public + content manager)
    'seminar_email_log',    -- "recent sends" in the registrants dialog
    'inquiry_attachments'   -- attachments shown on an inquiry in intake
  ] LOOP
    IF to_regclass('public.' || t) IS NULL THEN
      RAISE NOTICE 'public.% does not exist — skipped', t;
      CONTINUE;
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM pg_publication_tables
      WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = t
    ) THEN
      EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', t);
    END IF;
  END LOOP;
END $$;

-- ----------------------------------------------------------------------------
-- 3. Verify (read-only)
-- ----------------------------------------------------------------------------
DO $$
DECLARE
  v_pub     INTEGER;
  v_total   INTEGER;
  v_full    INTEGER;
  v_missing TEXT;
BEGIN
  SELECT count(*) INTO v_total FROM unnest(ARRAY[
    'profiles', 'matters', 'documents', 'matter_events', 'matter_members',
    'audit_logs', 'practice_areas', 'specialists', 'corporate_clients',
    'articles', 'faqs', 'seminar_events', 'retainer_packages',
    'seminar_email_log', 'inquiry_attachments'
  ]) t
  WHERE to_regclass('public.' || t) IS NOT NULL;

  SELECT count(*) INTO v_pub FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime' AND schemaname = 'public'
      AND tablename IN (
        'profiles', 'matters', 'documents', 'matter_events', 'matter_members',
        'audit_logs', 'practice_areas', 'specialists', 'corporate_clients',
        'articles', 'faqs', 'seminar_events', 'retainer_packages',
        'seminar_email_log', 'inquiry_attachments'
      );

  SELECT count(*) INTO v_full FROM pg_class
    WHERE oid IN (to_regclass('public.documents'), to_regclass('public.matter_members'),
                  to_regclass('public.notifications'))
      AND relreplident = 'f';

  SELECT string_agg(t, ', ') INTO v_missing FROM unnest(ARRAY[
    'profiles', 'matters', 'documents', 'matter_events', 'matter_members',
    'audit_logs', 'practice_areas', 'specialists', 'corporate_clients',
    'articles', 'faqs', 'seminar_events', 'retainer_packages',
    'seminar_email_log', 'inquiry_attachments'
  ]) t
  WHERE to_regclass('public.' || t) IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM pg_publication_tables
      WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = t
    );

  RAISE NOTICE '--------------------------------------------------------------';
  RAISE NOTICE 'remaining portal tables published (want all) : % / %', v_pub, v_total;
  RAISE NOTICE 'filtered-delete tables with identity full     : % / 3', v_full;
  RAISE NOTICE 'tables still missing from the publication     : %', COALESCE(v_missing, 'none');
  RAISE NOTICE '--------------------------------------------------------------';
END $$;


-- ############################################################################
-- ## 24/29  20261021_court_decisions_law_library.sql
-- ############################################################################
-- ============================================================================
-- 20261021 — Law Library: public Philippine jurisprudence
-- ============================================================================
-- Adds `court_decisions`, a public library of Supreme Court decisions rendered
-- on the site's "Law Library" page (mirroring the reference firm site's
-- structure). It is a content table in the same family as `articles`/`faqs`:
-- a TEXT id derived from the slug, an `is_published` gate, and admin CRUD from
-- the portal's Website Content manager. Visitors read published rows only.
--
-- Deliberately TWO policies (one public SELECT, one admin FOR ALL) rather than
-- the three the older `articles` table carries. The extra
-- `articles_authenticated_select` policy is what produces the
-- `multiple_permissive_policies` advisor finding the linter triage has to
-- accept; admin SELECT is already covered by the FOR ALL policy here.
--
-- The GRANTs are explicit on purpose. The live project's default privileges
-- did NOT cover the 20260918 content tables (the "Admin access is required"
-- failure fixed by 20261007), and the local harness cannot reproduce that gap
-- because it sets ALTER DEFAULT PRIVILEGES. Assert the end state the hard way
-- in scripts/local-pg-validate.sh.
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. Table
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.court_decisions (
  id            TEXT PRIMARY KEY,
  title         TEXT NOT NULL,
  slug          TEXT UNIQUE NOT NULL,
  gr_no         TEXT NOT NULL,
  division      TEXT,
  decision_date DATE NOT NULL,
  ponente       TEXT,
  category      TEXT,
  summary       TEXT NOT NULL,
  full_text     TEXT,
  is_published  BOOLEAN NOT NULL DEFAULT FALSE,
  published_at  TIMESTAMPTZ,
  view_count    INTEGER NOT NULL DEFAULT 0,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE public.court_decisions ENABLE ROW LEVEL SECURITY;

-- ----------------------------------------------------------------------------
-- 2. Policies
-- ----------------------------------------------------------------------------
-- Visitors read published decisions only.
DROP POLICY IF EXISTS court_decisions_public_select ON public.court_decisions;
CREATE POLICY court_decisions_public_select
ON public.court_decisions FOR SELECT
TO public
USING (is_published = true);

-- Admins manage every row. FOR ALL also grants admin SELECT.
DROP POLICY IF EXISTS court_decisions_admin_all ON public.court_decisions;
CREATE POLICY court_decisions_admin_all
ON public.court_decisions FOR ALL
TO authenticated
USING ((SELECT private.is_admin()))
WITH CHECK ((SELECT private.is_admin()));

-- ----------------------------------------------------------------------------
-- 3. Indexes + updated_at trigger
-- ----------------------------------------------------------------------------
CREATE INDEX IF NOT EXISTS idx_court_decisions_published
  ON public.court_decisions(is_published, decision_date DESC);
CREATE INDEX IF NOT EXISTS idx_court_decisions_category
  ON public.court_decisions(category);

DROP TRIGGER IF EXISTS court_decisions_updated_at ON public.court_decisions;
CREATE TRIGGER court_decisions_updated_at BEFORE UPDATE ON public.court_decisions
FOR EACH ROW EXECUTE FUNCTION public.update_updated_at();

-- ----------------------------------------------------------------------------
-- 4. Grants
-- ----------------------------------------------------------------------------
-- anon  : SELECT only — the public site reads published rows.
-- authed: full DML — the admin Content Manager writes; RLS filters the rest.
GRANT SELECT ON public.court_decisions TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.court_decisions TO authenticated, service_role;

-- ----------------------------------------------------------------------------
-- 5. Realtime (guarded, mirrors 20261020)
-- ----------------------------------------------------------------------------
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    RAISE NOTICE 'supabase_realtime publication not found — skipping realtime registration';
    RETURN;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime' AND schemaname = 'public'
      AND tablename = 'court_decisions'
  ) THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.court_decisions;
  END IF;
END $$;

-- ----------------------------------------------------------------------------
