-- ----------------------------------------------------------------------------
-- 7. Verify (read-only)
-- ----------------------------------------------------------------------------
DO $$
DECLARE
  v_total    INTEGER;
  v_policies INTEGER;
  v_realtime INTEGER;
BEGIN
  SELECT count(*) INTO v_total FROM public.court_decisions;
