-- ############################################################################
-- ## 25/29  20261022_contact_details.sql
-- ############################################################################
-- ============================================================================
-- 20261022 — Firm contact details: new public email + phone
-- ============================================================================
-- The site renders the firm's contact details from src/lib/firm.ts, but the
-- seeded FAQ answer is database content and still names the old address and
-- number. Fix it in place so the live FAQ matches the site.
--
-- Every old variant is replaced so the file converges a database seeded from
-- any earlier version of 20260919: some rows carry atty.boyet@westwoodlaw.ph
-- (the pre-20261009 address), others the interim westwoodlawfirm1@gmail.com.
-- Atty. Tabao's own directory email (public_lawyers.email) and his portal
-- login are deliberately left alone — only the firm's public "contact us"
-- details change.
--
-- Idempotent: on a database already carrying the new values the replacements
-- find nothing, and re-running the file is a no-op.
-- ============================================================================

UPDATE public.faqs
SET answer = replace(
               replace(
                 replace(
                   replace(answer,
                     '(02) 7957 2121', '+63 2 8722 9244'),
                   '(02) 722 9244', '+63 2 8722 9244'),
                 'westwoodlawfirm1@gmail.com', 'firmwestwoodlaw@gmail.com'),
               'atty.boyet@westwoodlaw.ph', 'firmwestwoodlaw@gmail.com')
WHERE answer LIKE '%(02) 7957 2121%'
   OR answer LIKE '%(02) 722 9244%'
   OR answer LIKE '%westwoodlawfirm1@gmail.com%'
   OR answer LIKE '%atty.boyet@westwoodlaw.ph%';

-- ----------------------------------------------------------------------------
-- Verify (read-only)
-- ----------------------------------------------------------------------------
DO $$
DECLARE
  v_stale INTEGER;
BEGIN
  SELECT count(*) INTO v_stale FROM public.faqs
   WHERE answer LIKE '%(02) 7957 2121%'
      OR answer LIKE '%(02) 722 9244%'
      OR answer LIKE '%westwoodlawfirm1@gmail.com%'
      OR answer LIKE '%atty.boyet@westwoodlaw.ph%';
  RAISE NOTICE 'faqs still naming an old contact detail: %', v_stale;
END $$;


-- ############################################################################
-- ## 26/29  20261023_role_expansion.sql
-- ############################################################################
-- ============================================================================
-- 20261023  Role expansion: the six-role model
-- ============================================================================
-- Run AFTER 20261022. Safe to re-run (verified twice by
-- scripts/local-pg-validate.sh).
--
-- The firm outgrew three roles. The single 'admin' role becomes two —
--   * managing_partner : inherits every power the old admin had
--   * system_admin     : technical role; manages accounts + reads the audit
--                        trail, but no legal work (no matters, notes,
--                        documents, break-glass)
-- and three new working roles join 'lawyer':
--   * legal_assistant  : intake. Sees the inquiry queue and is notified about
--                        new client inquiries, together with the managing
--                        partner.
--   * paralegal        : can be added to a matter team. Sees the matter,
--                        internal notes, timeline and non-confidential
--                        documents; cannot change matter status, reassign
--                        lawyers, or open Confidential documents.
--
-- Decisions implemented (from the owner, 2026-10-13):
--   * Extend the role enum; keep RLS-policy enforcement (no permissions table).
--   * Existing admins migrate to managing_partner.
--   * Managing partner AND system admin manage staff accounts.
--   * Paralegals join matter teams (with the Confidential limits above).
--   * Intake + managing partner both get the new-inquiry bell.
--
-- WHY THE TEMP-TYPE SWAP (and not ALTER TYPE ... ADD VALUE):
--   The owner applies this file by pasting it into the Supabase SQL Editor as
--   one run, and a value added by ALTER TYPE ... ADD VALUE cannot be USED in
--   the same run. So: create user_role_new, move the column with a CASE that
--   maps admin -> managing_partner, drop the old type, rename the new one.
--
-- WHAT THE OLD TYPE PULLED WITH IT (found with pg_depend, not by guessing):
--   * column profiles.role + its default        -> handled by ALTER COLUMN TYPE
--   * function private.get_user_role()          -> return type changes, must
--                                                  be dropped and recreated
--   * policy profiles_update_own / profiles_update_policy (one per database
--     shape: the live project has the first, a replayed chain the second)
--   * policy inquiries_select_assigned_lawyer / inquiries_update_assigned_lawyer
--   * the public_lawyers view's rule
--   * policies lawyer_photos_insert / lawyer_photos_update / lawyer_photos_delete
--     (storage.objects): the live project's dashboard-era copies compare
--     profiles.role DIRECTLY — a column dependency, which ALTER COLUMN TYPE
--     refuses with 0A000 (hit on the first live paste of this file). They are
--     dropped and rebuilt against private.is_admin().
--   Everything else that mentions the old role names lives inside function
--   bodies, which CREATE OR REPLACE re-parses — so the ~30 policies calling
--   private.is_admin() and friends keep working untouched, as long as the
--   function is recreated under the same name (OIDs are preserved).
-- ============================================================================


-- ----------------------------------------------------------------------------
-- 1. Drop the objects the old type drags down with it
-- ----------------------------------------------------------------------------
-- The "own-row UPDATE, role unchanged" rule exists under two names depending
-- on how the database was built: profiles_update_own (schema-production.sql,
-- i.e. the live project) or profiles_update_policy (20260918, i.e. a database
-- that replayed every migration file). Each shape has exactly one. Both are
-- dropped, and step 4 recreates the single canonical name
-- (profiles_update_own) on either shape — identical rule, no extra policy.
DROP POLICY IF EXISTS profiles_update_own ON public.profiles;
DROP POLICY IF EXISTS profiles_update_policy ON public.profiles;
DROP POLICY IF EXISTS inquiries_select_assigned_lawyer ON public.inquiries;
DROP POLICY IF EXISTS inquiries_update_assigned_lawyer ON public.inquiries;

-- The live project's dashboard-era lawyer-photos storage policies compare
-- public.profiles.role DIRECTLY (schema-production.sql's copies call
-- private.is_admin(), but the live rows never were rebuilt). A policy
-- dependency on the column blocks ALTER COLUMN TYPE with 0A000 — the exact
-- error the first live paste of this file died on — so they are dropped here
-- and rebuilt in step 4 against the function.
DROP POLICY IF EXISTS lawyer_photos_insert ON storage.objects;
DROP POLICY IF EXISTS lawyer_photos_update ON storage.objects;
DROP POLICY IF EXISTS lawyer_photos_delete ON storage.objects;

-- get_user_role() returns the enum by value, so its return type is part of its
-- identity: DROP is the only way to change it. The view's stored rule holds a
-- direct reference to the old type, so it has to be rebuilt too.
DROP FUNCTION IF EXISTS private.get_user_role();
DROP VIEW IF EXISTS public.public_lawyers;


-- ----------------------------------------------------------------------------
-- 2. Swap the enum
-- ----------------------------------------------------------------------------
-- The column default is an expression over the OLD type, and there is no
-- implicit cast between two enum types, so ALTER COLUMN TYPE refuses to carry
-- it. Drop it, move the column, put it back against the new type.
ALTER TABLE public.profiles ALTER COLUMN role DROP DEFAULT;

DROP TYPE IF EXISTS public.user_role_new;
CREATE TYPE public.user_role_new AS ENUM
  ('client', 'lawyer', 'legal_assistant', 'paralegal', 'managing_partner', 'system_admin');

ALTER TABLE public.profiles
  ALTER COLUMN role TYPE public.user_role_new
  USING (CASE role::TEXT WHEN 'admin' THEN 'managing_partner' ELSE role::TEXT END)::public.user_role_new;

-- Fails loudly (the whole paste rolls back) if any dependent was missed — by
-- design, so a half-swapped database can never exist.
DROP TYPE public.user_role;
ALTER TYPE public.user_role_new RENAME TO user_role;

ALTER TABLE public.profiles ALTER COLUMN role SET DEFAULT 'client'::public.user_role;


-- ----------------------------------------------------------------------------
-- 3. Recreate the helpers against the new type
-- ----------------------------------------------------------------------------
-- is_admin() keeps its name and now means "managing partner" — the role that
-- inherited every power the old admin had. Every policy written against
-- is_admin() therefore keeps exactly the access it had, with zero policy
-- churn. The ::TEXT comparisons also make this file re-runnable: on a second
-- pass the literal is never cast to the enum, so nothing can fail to fold.

CREATE FUNCTION private.get_user_role()
RETURNS public.user_role
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
AS $$
  SELECT p.role
  FROM public.profiles AS p
  WHERE p.id = (SELECT auth.uid())
    AND COALESCE(p.is_active, TRUE)
    AND p.deleted_at IS NULL
  LIMIT 1;
$$;

CREATE OR REPLACE FUNCTION private.is_admin()
RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles AS p
    WHERE p.id = (SELECT auth.uid())
      AND p.role::TEXT = 'managing_partner'
      AND COALESCE(p.is_active, TRUE)
      AND p.deleted_at IS NULL
  );
$$;

CREATE OR REPLACE FUNCTION private.is_system_admin()
RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles AS p
    WHERE p.id = (SELECT auth.uid())
      AND p.role::TEXT = 'system_admin'
      AND COALESCE(p.is_active, TRUE)
      AND p.deleted_at IS NULL
  );
$$;

-- Staff account management: the managing partner and the system admin.
CREATE OR REPLACE FUNCTION private.is_staff_account_admin()
RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles AS p
    WHERE p.id = (SELECT auth.uid())
      AND p.role::TEXT IN ('managing_partner', 'system_admin')
      AND COALESCE(p.is_active, TRUE)
      AND p.deleted_at IS NULL
  );
$$;

-- Firm staff = everyone except clients. Used for the staff-facing surfaces
-- (staff directory, lawyer directory, inquiry attachments). The system admin
-- is trusted IT and belongs here; the legal-work boundaries are enforced by
-- is_admin()/team checks elsewhere, where the system admin does NOT appear.
CREATE OR REPLACE FUNCTION private.is_lawyer_or_admin()
RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles AS p
    WHERE p.id = (SELECT auth.uid())
      AND p.role::TEXT IN ('lawyer', 'legal_assistant', 'paralegal', 'managing_partner', 'system_admin')
      AND COALESCE(p.is_active, TRUE)
      AND p.deleted_at IS NULL
  );
$$;

CREATE OR REPLACE FUNCTION private.is_intake()
RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = ''
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles AS p
    WHERE p.id = (SELECT auth.uid())
      AND p.role::TEXT = 'legal_assistant'
      AND COALESCE(p.is_active, TRUE)
      AND p.deleted_at IS NULL
  );
$$;

CREATE OR REPLACE FUNCTION private.is_active_lawyer(p_id UUID) RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE p.id = p_id
      AND p.role::TEXT = 'lawyer'
      AND COALESCE(p.is_active, TRUE)
      AND p.deleted_at IS NULL
  );
$$;

-- The lawyer team = assigned lawyer + team members whose profile role is
-- 'lawyer'. UNCHANGED in meaning: paralegals may now be matter_members, but
-- they are deliberately NOT in this set — Confidential content, break-glass
-- scope and status transitions stay lawyer-only.
CREATE OR REPLACE FUNCTION private.is_matter_lawyer_team(p_matter_id UUID) RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT EXISTS (SELECT 1 FROM public.matters m WHERE m.id = p_matter_id AND m.lawyer_id = (SELECT auth.uid()))
      OR EXISTS (SELECT 1 FROM public.matter_members mm
                 JOIN public.profiles p ON p.id = mm.lawyer_id
                 WHERE mm.matter_id = p_matter_id
                   AND mm.lawyer_id = (SELECT auth.uid())
                   AND p.role::TEXT = 'lawyer');
$$;

-- The full matter team = assigned lawyer + any member (lawyer OR paralegal).
-- Used where case support should count: matter access, notes, timeline.
CREATE OR REPLACE FUNCTION private.is_matter_team(p_matter_id UUID) RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT EXISTS (SELECT 1 FROM public.matters m WHERE m.id = p_matter_id AND m.lawyer_id = (SELECT auth.uid()))
      OR EXISTS (SELECT 1 FROM public.matter_members mm
                 WHERE mm.matter_id = p_matter_id AND mm.lawyer_id = (SELECT auth.uid()));
$$;

-- Anyone connected to the matter: client, matter team (incl. paralegals), MP.
CREATE OR REPLACE FUNCTION private.user_can_access_matter(p_matter_id UUID) RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT EXISTS (SELECT 1 FROM public.matters m WHERE m.id = p_matter_id AND m.client_id = (SELECT auth.uid()))
      OR private.is_matter_team(p_matter_id)
      OR (SELECT private.is_admin());
$$;

REVOKE ALL ON FUNCTION private.get_user_role() FROM PUBLIC;
REVOKE ALL ON FUNCTION private.is_admin() FROM PUBLIC;
REVOKE ALL ON FUNCTION private.is_system_admin() FROM PUBLIC;
REVOKE ALL ON FUNCTION private.is_staff_account_admin() FROM PUBLIC;
REVOKE ALL ON FUNCTION private.is_lawyer_or_admin() FROM PUBLIC;
REVOKE ALL ON FUNCTION private.is_intake() FROM PUBLIC;
REVOKE ALL ON FUNCTION private.is_active_lawyer(UUID) FROM PUBLIC;
REVOKE ALL ON FUNCTION private.is_matter_lawyer_team(UUID) FROM PUBLIC;
REVOKE ALL ON FUNCTION private.is_matter_team(UUID) FROM PUBLIC;
REVOKE ALL ON FUNCTION private.user_can_access_matter(UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION private.get_user_role() TO authenticated;
GRANT EXECUTE ON FUNCTION private.is_admin() TO authenticated;
GRANT EXECUTE ON FUNCTION private.is_system_admin() TO authenticated;
GRANT EXECUTE ON FUNCTION private.is_staff_account_admin() TO authenticated;
GRANT EXECUTE ON FUNCTION private.is_lawyer_or_admin() TO authenticated;
GRANT EXECUTE ON FUNCTION private.is_intake() TO authenticated;
GRANT EXECUTE ON FUNCTION private.is_active_lawyer(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION private.is_matter_lawyer_team(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION private.is_matter_team(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION private.user_can_access_matter(UUID) TO authenticated;


-- ----------------------------------------------------------------------------
-- 4. Recreate the policies the swap forced us to drop
-- ----------------------------------------------------------------------------
-- Texts match what each database had (auth.uid() stays wrapped as
-- (SELECT auth.uid()) so the auth_rls_initplan advisor stays quiet). The
-- profile policy is recreated under the canonical name on every shape — see
-- the note in step 1.
CREATE POLICY profiles_update_own ON public.profiles
FOR UPDATE TO authenticated
USING ((SELECT auth.uid()) = id)
WITH CHECK (
  (SELECT auth.uid()) = id
  AND role = (SELECT private.get_user_role())
);

CREATE POLICY inquiries_select_assigned_lawyer ON public.inquiries
FOR SELECT TO authenticated
USING (
  assigned_to = (SELECT auth.uid())
  AND (SELECT private.get_user_role()) = 'lawyer'::public.user_role
);

CREATE POLICY inquiries_update_assigned_lawyer ON public.inquiries
FOR UPDATE TO authenticated
USING (
  assigned_to = (SELECT auth.uid())
  AND (SELECT private.get_user_role()) = 'lawyer'::public.user_role
)
WITH CHECK (
  assigned_to = (SELECT auth.uid())
  AND (SELECT private.get_user_role()) = 'lawyer'::public.user_role
);

-- The lawyer-photos write policies, rebuilt against the helper (the live
-- project's copies compared profiles.role directly — see step 1). is_admin()
-- now means managing partner, so the access the old admin had is preserved
-- exactly. lawyer_photos_select stays dropped: 20261005 removed it so the
-- public bucket cannot be enumerated.
CREATE POLICY lawyer_photos_insert ON storage.objects
FOR INSERT TO authenticated
WITH CHECK (bucket_id = 'lawyer-photos' AND (SELECT private.is_admin()));

CREATE POLICY lawyer_photos_update ON storage.objects
FOR UPDATE TO authenticated
USING (bucket_id = 'lawyer-photos' AND (SELECT private.is_admin()))
WITH CHECK (bucket_id = 'lawyer-photos' AND (SELECT private.is_admin()));

CREATE POLICY lawyer_photos_delete ON storage.objects
FOR DELETE TO authenticated
USING (bucket_id = 'lawyer-photos' AND (SELECT private.is_admin()));


-- ----------------------------------------------------------------------------
-- 5. Rebuild the public lawyer directory view
-- ----------------------------------------------------------------------------
-- Definition identical to 20261001 (a SECURITY DEFINER view on purpose — it IS
-- the public boundary; see the accepted advisor finding security_definer_view).
CREATE OR REPLACE VIEW public.public_lawyers AS
SELECT p.id, p.email, p.honorific, p.first_name, p.nickname, p.middle_name, p.last_name, p.suffix, p.full_name,
       p.position, p.bio, p.education, p.bar_admissions, p.experience_years, p.profile_image,
       p.linkedin_url, p.display_order, p.city,
       COALESCE((SELECT jsonb_agg(jsonb_build_object('id', pa.id, 'name', pa.name, 'slug', pa.slug, 'icon', pa.icon)
                                  ORDER BY pa.display_order)
                 FROM public.profile_practice_areas ppa
                 JOIN public.practice_areas pa ON pa.id = ppa.practice_area_id AND pa.is_active
                 WHERE ppa.profile_id = p.id), '[]'::JSONB) AS practice_areas
FROM public.profiles p
WHERE p.role = 'lawyer' AND COALESCE(p.is_active, TRUE) AND p.deleted_at IS NULL;
GRANT SELECT ON public.public_lawyers TO anon, authenticated;


-- ----------------------------------------------------------------------------
-- 6. Functions whose bodies hard-coded the old role names
-- ----------------------------------------------------------------------------
-- plpgsql bodies are resolved at run time, so these would have kept parsing
-- after the swap — and then failed the first time they ran. Rewritten here.

-- The firm must always keep at least one active managing partner. (The system
-- admin pool is not guarded: a managing partner can always recreate it, so
-- demoting the last system admin can never lock the firm out.)
CREATE OR REPLACE FUNCTION private.guard_last_admin() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_remaining INT;
BEGIN
  IF OLD.role::TEXT = 'managing_partner'
     AND COALESCE(OLD.is_active, TRUE)
     AND (NEW.role::TEXT IS DISTINCT FROM 'managing_partner'
          OR NOT COALESCE(NEW.is_active, TRUE)
          OR NEW.deleted_at IS NOT NULL) THEN

    SELECT count(*) INTO v_remaining
    FROM public.profiles p
    WHERE p.role::TEXT = 'managing_partner'
      AND COALESCE(p.is_active, TRUE)
      AND p.deleted_at IS NULL
      AND p.id <> OLD.id;

    IF v_remaining = 0 THEN
      RAISE EXCEPTION
        'This is the last active managing partner. Promote another account before changing this one.'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION private.guard_last_admin_delete() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_remaining INT;
BEGIN
  IF OLD.role::TEXT = 'managing_partner' AND COALESCE(OLD.is_active, TRUE) THEN
    SELECT count(*) INTO v_remaining
    FROM public.profiles p
    WHERE p.role::TEXT = 'managing_partner'
      AND COALESCE(p.is_active, TRUE)
      AND p.deleted_at IS NULL
      AND p.id <> OLD.id;

    IF v_remaining = 0 THEN
      RAISE EXCEPTION
        'This is the last active managing partner and cannot be deleted. Promote another account first.'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN OLD;
END $$;

-- Role/status/position changes: managing partner OR system admin (decision
-- 2026-10-13: both manage staff accounts).
CREATE OR REPLACE FUNCTION private.guard_profile_update() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF NEW.date_of_birth IS NOT NULL AND (NEW.date_of_birth > CURRENT_DATE OR NEW.date_of_birth < DATE '1900-01-01') THEN
    RAISE EXCEPTION 'Birthday must be a real past date';
  END IF;

  IF NEW.email IS DISTINCT FROM OLD.email AND auth.uid() IS NOT NULL THEN
    RAISE EXCEPTION 'Email addresses cannot be changed from the app. Contact the firm.';
  END IF;

  IF auth.uid() IS NULL OR private.is_staff_account_admin() THEN RETURN NEW; END IF;

  IF NEW.role IS DISTINCT FROM OLD.role
     OR NEW.is_active IS DISTINCT FROM OLD.is_active
     OR NEW.deleted_at IS DISTINCT FROM OLD.deleted_at
     OR NEW.position IS DISTINCT FROM OLD.position
     OR NEW.display_order IS DISTINCT FROM OLD.display_order THEN
    RAISE EXCEPTION 'You cannot change role, email, status, position or display order. Contact the firm.';
  END IF;
  RETURN NEW;
END $$;

-- Document metadata visibility. Paralegals see their matters' documents at
-- every level EXCEPT Confidential (lawyer team only, metadata for the MP);
-- 'Staff Shared' is firm-internal and includes paralegals; intake and the
-- system admin see no matter documents at all.
CREATE OR REPLACE FUNCTION private.can_access_document(p_matter_id UUID, p_access_level public.access_level)
RETURNS BOOLEAN LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_uid UUID := (SELECT auth.uid()); v_role public.user_role; v_client UUID;
BEGIN
  SELECT p.role INTO v_role FROM public.profiles p WHERE p.id = v_uid;
  SELECT m.client_id INTO v_client FROM public.matters m WHERE m.id = p_matter_id;
  RETURN CASE p_access_level
    WHEN 'Public'       THEN TRUE
    WHEN 'Staff Shared' THEN v_role::TEXT IN ('lawyer', 'paralegal', 'managing_partner')
    WHEN 'Client & Assigned Lawyer' THEN v_uid = v_client OR private.is_matter_team(p_matter_id) OR v_role::TEXT = 'managing_partner'
    WHEN 'Lawyer Only'  THEN private.is_matter_lawyer_team(p_matter_id) OR v_role::TEXT = 'managing_partner'
    WHEN 'Confidential' THEN private.is_matter_lawyer_team(p_matter_id) OR v_role::TEXT = 'managing_partner'  -- MP: metadata only
    ELSE FALSE END;
END $$;

-- Who may author a document. The managing partner stays view-only (20261012).
-- Paralegals may file on matters they are on, but never author Confidential.
CREATE OR REPLACE FUNCTION private.can_upload_document(p_matter_id UUID, p_access_level public.access_level)
RETURNS BOOLEAN LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF NOT private.user_can_access_matter(p_matter_id) THEN RETURN FALSE; END IF;
  RETURN CASE private.get_user_role()
    WHEN 'managing_partner' THEN FALSE           -- view-only: the MP never authors documents
    WHEN 'lawyer' THEN private.is_matter_lawyer_team(p_matter_id)
                       AND p_access_level IN ('Client & Assigned Lawyer','Staff Shared','Lawyer Only','Confidential')
    WHEN 'paralegal' THEN private.is_matter_team(p_matter_id)
                       AND p_access_level IN ('Client & Assigned Lawyer','Staff Shared','Lawyer Only')
    WHEN 'client' THEN p_access_level = 'Client & Assigned Lawyer'
    ELSE FALSE END;
END $$;

-- Matter teams accept lawyers AND paralegals. Everyone else is still refused.
CREATE OR REPLACE FUNCTION private.on_matter_member_change() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE r public.matter_members; v_assigned UUID;
BEGIN
  r := CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  SELECT lawyer_id INTO v_assigned FROM public.matters WHERE id = r.matter_id;
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = r.lawyer_id AND role::TEXT IN ('lawyer', 'paralegal')) THEN
      RAISE EXCEPTION 'Only lawyers and paralegals can be added to a matter team';
    END IF;
    NEW.added_by := auth.uid();
  END IF;
  PERFORM private.write_audit('MATTER_TEAM_' || TG_OP, 'Matter team member ' || lower(TG_OP), 'matter', r.matter_id::TEXT,
    jsonb_build_object('lawyer_id', r.lawyer_id));
  IF v_assigned IS NOT NULL AND v_assigned IS DISTINCT FROM auth.uid() THEN
    PERFORM private.create_notification(v_assigned, 'Matter team changed',
      'A team member was ' || CASE WHEN TG_OP='INSERT' THEN 'added to' ELSE 'removed from' END || ' one of your matters.', 'info', 'matters');
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;

-- New client inquiries ring the bell for the managing partner AND intake
-- (decision 2026-10-13: intake owns first response).
CREATE OR REPLACE FUNCTION private.notify_admins_new_inquiry()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_admin   UUID;
  v_who     TEXT;
  v_subject TEXT;
BEGIN
  IF NEW.client_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_who := COALESCE(NULLIF(btrim(NEW.name), ''), 'A client');
  v_subject := NULLIF(btrim(NEW.subject), '');

  FOR v_admin IN
    SELECT p.id
    FROM public.profiles AS p
    WHERE p.role::TEXT IN ('managing_partner', 'legal_assistant')
      AND COALESCE(p.is_active, TRUE)
      AND p.deleted_at IS NULL
  LOOP
    PERFORM private.create_notification(
      v_admin,
      'New client inquiry',
      v_who || ' submitted ' || NEW.inquiry_number || COALESCE(' — ' || v_subject, ''),
      'info',
      'intake'
    );
  END LOOP;

  RETURN NEW;
END $$;

-- A matter's assigned lawyer must be a lawyer — the old body also accepted
-- 'admin', which no longer exists and was never exercised by the app
-- (convert_inquiry_to_matter validates role = 'lawyer' already).
CREATE OR REPLACE FUNCTION private.validate_matter_staff()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  IF NEW.lawyer_id IS NOT NULL AND NOT EXISTS (
    SELECT 1
    FROM public.profiles AS p
    WHERE p.id = NEW.lawyer_id
      AND p.role::TEXT = 'lawyer'
  ) THEN
    RAISE EXCEPTION 'lawyer_id must reference a lawyer profile';
  END IF;

  RETURN NEW;
END $$;


-- ----------------------------------------------------------------------------
-- 7. Policy updates that the paralegal team membership requires
-- ----------------------------------------------------------------------------
-- Internal notes + timeline: the full matter team (lawyers and paralegals)
-- reads and writes internal notes; client-visible updates remain lawyer-
-- authored (and the MP's client-visible path is unchanged); clients keep the
-- 20261004 insert policy of their own.

DROP POLICY IF EXISTS matter_notes_select ON public.matter_notes;
CREATE POLICY matter_notes_select ON public.matter_notes FOR SELECT TO authenticated
  USING ((SELECT private.is_matter_team(matter_id))
      OR (visibility = 'client' AND (SELECT private.user_can_access_matter(matter_id))));

DROP POLICY IF EXISTS matter_notes_insert ON public.matter_notes;
CREATE POLICY matter_notes_insert ON public.matter_notes FOR INSERT TO authenticated
  WITH CHECK (author_id = (SELECT auth.uid())
    AND ((SELECT private.is_matter_lawyer_team(matter_id))
      OR ((SELECT private.is_matter_team(matter_id)) AND visibility = 'internal')
      OR (visibility = 'client' AND (SELECT private.is_admin()))));

DROP POLICY IF EXISTS matter_events_select ON public.matter_events;
CREATE POLICY matter_events_select ON public.matter_events FOR SELECT TO authenticated
  USING ((visible_to_client AND (SELECT private.user_can_access_matter(matter_id)))
      OR (SELECT private.is_matter_team(matter_id)) OR (SELECT private.is_admin()));


-- ----------------------------------------------------------------------------
-- 8. New surfaces for the new roles
-- ----------------------------------------------------------------------------
-- Intake works the inquiry queue: SELECT on every inquiry (their first-response
-- list). Acting on one still runs through the existing guards — the assigned-
-- lawyer policy and guard_inquiry_update() are untouched.
DROP POLICY IF EXISTS inquiries_select_intake ON public.inquiries;
CREATE POLICY inquiries_select_intake ON public.inquiries
FOR SELECT TO authenticated
USING ((SELECT private.is_intake()));

-- The system admin manages accounts: full UPDATE on profiles, still bounded by
-- guard_profile_update() (which allows role/status edits for account admins)
-- and by the last-managing-partner guard.
DROP POLICY IF EXISTS profiles_update_system_admin ON public.profiles;
CREATE POLICY profiles_update_system_admin ON public.profiles
FOR UPDATE TO authenticated
USING ((SELECT private.is_system_admin()))
WITH CHECK ((SELECT private.is_system_admin()));

-- The system admin reviews the audit trail.
DROP POLICY IF EXISTS audit_logs_select_system_admin ON public.audit_logs;
CREATE POLICY audit_logs_select_system_admin ON public.audit_logs
FOR SELECT TO authenticated
USING ((SELECT private.is_system_admin()));


-- ----------------------------------------------------------------------------
-- 9. Verify (read-only)
-- ----------------------------------------------------------------------------
DO $$
DECLARE
  v_values    TEXT;
  v_count     INT;
  v_missing   TEXT := '';
  v_mps       INT;
BEGIN
  SELECT string_agg(e.enumlabel, ',' ORDER BY e.enumsortorder) INTO v_values
  FROM pg_enum e JOIN pg_type t ON t.oid = e.enumtypid
  JOIN pg_namespace n ON n.oid = t.typnamespace
  WHERE n.nspname = 'public' AND t.typname = 'user_role';
  SELECT count(*) INTO v_count FROM pg_enum e JOIN pg_type t ON t.oid = e.enumtypid
  JOIN pg_namespace n ON n.oid = t.typnamespace
  WHERE n.nspname = 'public' AND t.typname = 'user_role';

  IF v_count <> 6
     OR EXISTS (SELECT 1 FROM pg_enum e JOIN pg_type t ON t.oid = e.enumtypid
                JOIN pg_namespace n ON n.oid = t.typnamespace
                WHERE n.nspname = 'public' AND t.typname = 'user_role' AND e.enumlabel = 'admin') THEN
    v_missing := v_missing || ' enum-not-swapped(' || v_values || ')';
  END IF;
  IF to_regprocedure('private.get_user_role()') IS NULL THEN
    v_missing := v_missing || ' no-get_user_role';
  END IF;
  IF to_regprocedure('private.is_system_admin()') IS NULL THEN
    v_missing := v_missing || ' no-is_system_admin';
  END IF;
  IF to_regprocedure('private.is_staff_account_admin()') IS NULL THEN
    v_missing := v_missing || ' no-is_staff_account_admin';
  END IF;
  IF to_regprocedure('private.is_matter_team(uuid)') IS NULL THEN
    v_missing := v_missing || ' no-is_matter_team';
  END IF;
  IF to_regclass('public.public_lawyers') IS NULL THEN
    v_missing := v_missing || ' no-public_lawyers';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies
                 WHERE schemaname = 'public' AND tablename = 'inquiries'
                   AND policyname = 'inquiries_select_intake') THEN
    v_missing := v_missing || ' no-intake-policy';
  END IF;

  SELECT count(*) INTO v_mps FROM public.profiles
  WHERE role::TEXT = 'managing_partner' AND COALESCE(is_active, TRUE) AND deleted_at IS NULL;

  RAISE NOTICE '--------------------------------------------------------------';
  RAISE NOTICE 'user_role values (want 6, no admin)     : %', v_values;
  RAISE NOTICE 'active managing partners                : %', v_mps;
  RAISE NOTICE '--------------------------------------------------------------';
  IF v_missing = '' THEN
    RAISE NOTICE 'role expansion: OK';
  ELSE
    RAISE WARNING 'role expansion: INCOMPLETE —%', v_missing;
  END IF;
  IF v_mps = 0 THEN
    RAISE WARNING 'There is no active managing partner. Promote one (a managing partner or system admin can do it from Staff Management).';
  END IF;
END $$;


-- ############################################################################
-- ## 27/29  20261024_tasks_and_reviews.sql
-- ############################################################################
-- ============================================================================
-- 20261024  Tasks + reviews (Phase B of the 6-role build)
-- ============================================================================
-- Run AFTER 20261023 (needs the six-role helpers: is_matter_team(),
-- is_matter_lawyer_team(), is_admin(), is_staff_account_admin()).
-- Safe to re-run (verified twice by scripts/local-pg-validate.sh).
--
-- Firm staff work matters through assigned tasks with an optional review gate:
--
--   * tasks        — one row per unit of work on a matter: assignee, creator,
--                    status, priority, due date, review requirement.
--   * task_reviews — immutable review decisions (Approved / Changes
--                    Requested). Four-eyes: a task can never be reviewed by
--                    its own assignee.
--   * task_events  — the per-task timeline, mirroring matter_events.
--
-- WHO CAN DO WHAT (decisions implemented):
--   * Create tasks       : matter lawyers on their own matters, managing
--                          partner on any matter. (Not system_admin — no
--                          legal work; not paralegals — they execute.)
--   * See a task         : assignee, creator, the matter team (lawyers AND
--                          paralegals), managing partner. Never clients.
--   * Move status        : assignee or a manager (matter lawyer / creator /
--                          MP) — but only along the transition matrix in
--                          private.guard_task_write().
--   * Reassign / cancel  : managers only (guard-enforced).
--   * Review             : matter lawyer, task creator or MP; never the
--                          assignee. Reviewing requires status In Review.
--   * Completion rule    : a task with requires_review = TRUE reaches
--                          Completed ONLY through an approved review row.
--                          Simple tasks complete directly from In Progress.
--
-- Notifications (private.create_notification, which skips the actor):
--   assigned / reassigned → assignee; ready for review → creator;
--   review decision → assignee; cancelled → assignee.
--   Completed-by-review is announced by apply_task_review() with the
--   decision text, so log_task_change() stays silent for Completed.
--
-- Realtime: tasks, task_reviews and task_events join the
-- supabase_realtime publication; the frontend treats each event as
-- "something changed, refetch" and each table's SELECT policy stays the
-- security boundary.
--
-- All three tables: RLS enabled, anon revoked, no DELETE policy (cancel,
-- don't delete — history stays intact; matter deletion cascades).
-- ============================================================================


-- ----------------------------------------------------------------------------
-- 1. Enums
-- ----------------------------------------------------------------------------
-- CREATE TYPE has no IF NOT EXISTS; catch duplicate_object so a second pass
-- is a no-op. The verification block below re-checks the exact value lists.
DO $$ BEGIN
  CREATE TYPE public.task_status AS ENUM
    ('Open', 'In Progress', 'Blocked', 'In Review', 'Completed', 'Cancelled');
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

DO $$ BEGIN
  CREATE TYPE public.review_decision AS ENUM
    ('Approved', 'Changes Requested');
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;


-- ----------------------------------------------------------------------------
-- 2. Tables
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.tasks (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  matter_id       UUID NOT NULL REFERENCES public.matters(id) ON DELETE CASCADE,
  title           TEXT NOT NULL CHECK (char_length(btrim(title)) BETWEEN 1 AND 300),
  description     TEXT CHECK (description IS NULL OR char_length(description) <= 5000),
  assigned_to     UUID NOT NULL REFERENCES public.profiles(id) ON DELETE RESTRICT,
  assigned_by     UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  status          public.task_status NOT NULL DEFAULT 'Open',
  priority        public.priority_level NOT NULL DEFAULT 'Medium',
  due_date        DATE,
  requires_review BOOLEAN NOT NULL DEFAULT FALSE,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.task_reviews (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  task_id     UUID NOT NULL REFERENCES public.tasks(id) ON DELETE CASCADE,
  reviewer_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE RESTRICT,
  decision    public.review_decision NOT NULL,
  comment     TEXT CHECK (comment IS NULL OR char_length(comment) <= 5000),
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.task_events (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  task_id    UUID NOT NULL REFERENCES public.tasks(id) ON DELETE CASCADE,
  event_type TEXT NOT NULL,
  title      TEXT NOT NULL,
  detail     TEXT,
  actor_id   UUID REFERENCES public.profiles(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Indexes: the two the UI leans on (my tasks by status; a matter's task
-- list), plus one per foreign key so the advisor's unindexed_foreign_keys
-- check stays quiet.
CREATE INDEX IF NOT EXISTS idx_tasks_assignee_status ON public.tasks(assigned_to, status);
CREATE INDEX IF NOT EXISTS idx_tasks_matter_created  ON public.tasks(matter_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_tasks_assigned_by     ON public.tasks(assigned_by);
CREATE INDEX IF NOT EXISTS idx_task_reviews_task     ON public.task_reviews(task_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_task_reviews_reviewer ON public.task_reviews(reviewer_id);
CREATE INDEX IF NOT EXISTS idx_task_events_task      ON public.task_events(task_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_task_events_actor     ON public.task_events(actor_id);

ALTER TABLE public.tasks        ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.task_reviews ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.task_events  ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.tasks, public.task_reviews, public.task_events FROM anon;

DROP TRIGGER IF EXISTS tasks_updated_at ON public.tasks;
CREATE TRIGGER tasks_updated_at BEFORE UPDATE ON public.tasks
FOR EACH ROW EXECUTE FUNCTION public.update_updated_at();


-- ----------------------------------------------------------------------------
-- 3. Write guard: validation + the transition matrix
-- ----------------------------------------------------------------------------
-- Runs on INSERT (force assigned_by, validate the assignee) and on UPDATE
-- (immutable fields, reassignment rights, status matrix, completion rule).
CREATE OR REPLACE FUNCTION private.guard_task_write() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_uid      UUID := (SELECT auth.uid());
  v_manager  BOOLEAN;
  v_assignee BOOLEAN;
BEGIN
  IF v_uid IS NULL THEN RETURN NEW; END IF;  -- SQL editor / service role

  -- The assignee must be active firm staff: never a client, never a
  -- deactivated or soft-deleted account.
  IF TG_OP = 'INSERT' OR NEW.assigned_to IS DISTINCT FROM OLD.assigned_to THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.profiles p
      WHERE p.id = NEW.assigned_to
        AND p.role::TEXT <> 'client'
        AND COALESCE(p.is_active, TRUE)
        AND p.deleted_at IS NULL
    ) THEN
      RAISE EXCEPTION 'Tasks can only be assigned to active firm staff';
    END IF;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.assigned_by := v_uid;   -- the creator is whoever inserts the row
    RETURN NEW;
  END IF;

  IF NEW.matter_id IS DISTINCT FROM OLD.matter_id
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.assigned_by IS DISTINCT FROM OLD.assigned_by THEN
    RAISE EXCEPTION 'Task matter, creator and creation time cannot be changed';
  END IF;

  v_manager  := private.is_admin()
                OR private.is_matter_lawyer_team(OLD.matter_id)
                OR OLD.assigned_by = v_uid;
  v_assignee := OLD.assigned_to = v_uid;

  IF NEW.assigned_to IS DISTINCT FROM OLD.assigned_to AND NOT v_manager THEN
    RAISE EXCEPTION 'Only a matter lawyer or the managing partner can reassign a task';
  END IF;

  IF NEW.requires_review IS DISTINCT FROM OLD.requires_review AND NOT v_manager THEN
    RAISE EXCEPTION 'Only a matter lawyer or the managing partner can change the review requirement';
  END IF;

  -- A plain assignee moves status; the task's description of the work stays
  -- with the managers.
  IF NOT v_manager AND (NEW.title IS DISTINCT FROM OLD.title
     OR NEW.description IS DISTINCT FROM OLD.description
     OR NEW.priority IS DISTINCT FROM OLD.priority
     OR NEW.due_date IS DISTINCT FROM OLD.due_date) THEN
    RAISE EXCEPTION 'Only a matter lawyer or the managing partner can change task details';
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NOT (v_assignee OR v_manager) THEN
      RAISE EXCEPTION 'Only the assignee, a matter lawyer or the managing partner can move a task';
    END IF;
    IF OLD.status IN ('Completed', 'Cancelled') THEN
      RAISE EXCEPTION 'Task is already % and cannot be reopened', OLD.status;
    END IF;
    IF NEW.status = 'Cancelled' AND NOT v_manager THEN
      RAISE EXCEPTION 'Only a matter lawyer or the managing partner can cancel a task';
    END IF;

    -- The completion rule: with requires_review, Completed is reachable only
    -- from In Review and only while the latest review decision is Approved
    -- (apply_task_review() inserts that row just before it flips the status).
    IF NEW.status = 'Completed' THEN
      IF OLD.status = 'In Review' AND EXISTS (
        SELECT 1 FROM public.task_reviews r
        WHERE r.task_id = OLD.id
          AND r.created_at = (SELECT max(r2.created_at) FROM public.task_reviews r2 WHERE r2.task_id = OLD.id)
          AND r.decision = 'Approved'
      ) THEN
        NULL;  -- approved review on record: completion allowed
      ELSIF NOT OLD.requires_review AND OLD.status = 'In Progress' THEN
        NULL;  -- simple task, completed directly by assignee or manager
      ELSIF OLD.requires_review THEN
        RAISE EXCEPTION 'This task requires review: it is completed through an approved review';
      ELSE
        RAISE EXCEPTION 'A task can only be completed from In Progress';
      END IF;
    END IF;

    IF NEW.status <> 'Cancelled' AND NOT (CASE OLD.status
      WHEN 'Open'        THEN NEW.status IN ('In Progress', 'Blocked', 'In Review')
      WHEN 'In Progress' THEN NEW.status IN ('Open', 'In Review', 'Blocked', 'Completed')
      WHEN 'Blocked'     THEN NEW.status IN ('In Progress', 'Open')
      WHEN 'In Review'   THEN NEW.status IN ('In Progress', 'Completed')
      ELSE FALSE END) THEN
      RAISE EXCEPTION 'Status cannot move from % to %', OLD.status, NEW.status;
    END IF;
  END IF;

  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS tasks_guard_write ON public.tasks;
CREATE TRIGGER tasks_guard_write BEFORE INSERT OR UPDATE ON public.tasks
FOR EACH ROW EXECUTE FUNCTION private.guard_task_write();


-- ----------------------------------------------------------------------------
-- 4. Review guard + effect
-- ----------------------------------------------------------------------------
-- BEFORE INSERT: reviews are always recorded as their author; four-eyes (the
-- assignee can never review); the task must be In Review; reviewer must be a
-- matter lawyer, the task creator or the MP.
CREATE OR REPLACE FUNCTION private.guard_task_review() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_uid UUID := (SELECT auth.uid());
  t     RECORD;
BEGIN
  IF v_uid IS NULL THEN RETURN NEW; END IF;

  SELECT id, matter_id, assigned_to, assigned_by, status INTO t
  FROM public.tasks WHERE id = NEW.task_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Task not found';
  END IF;

  NEW.reviewer_id := v_uid;
  NEW.comment := NULLIF(btrim(COALESCE(NEW.comment, '')), '');

  IF t.status <> 'In Review' THEN
    RAISE EXCEPTION 'Only a task In Review can be reviewed';
  END IF;
  IF t.assigned_to = v_uid THEN
    RAISE EXCEPTION 'A task cannot be reviewed by its assignee';
  END IF;
  IF NOT (private.is_admin() OR private.is_matter_lawyer_team(t.matter_id) OR t.assigned_by = v_uid) THEN
    RAISE EXCEPTION 'Only a matter lawyer, the task creator or the managing partner can review';
  END IF;

  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS task_reviews_guard ON public.task_reviews;
CREATE TRIGGER task_reviews_guard BEFORE INSERT ON public.task_reviews
FOR EACH ROW EXECUTE FUNCTION private.guard_task_review();

-- AFTER INSERT: apply the decision (Approved → Completed, Changes Requested →
-- back to In Progress), write the timeline entry, notify the assignee with
-- the decision, and audit. The task UPDATE re-enters guard_task_write() as
-- the reviewer, which the matrix above allows.
CREATE OR REPLACE FUNCTION private.apply_task_review() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  t        RECORD;
  v_author TEXT;
BEGIN
  SELECT id, assigned_to, title INTO t FROM public.tasks WHERE id = NEW.task_id;
  IF NOT FOUND THEN RETURN NEW; END IF;

  UPDATE public.tasks
  SET status = CASE NEW.decision
                 WHEN 'Approved' THEN 'Completed'::public.task_status
                 ELSE 'In Progress'::public.task_status
               END
  WHERE id = NEW.task_id;

  INSERT INTO public.task_events(task_id, event_type, title, detail, actor_id)
  VALUES (NEW.task_id, 'review', 'Review: ' || NEW.decision::TEXT, NEW.comment, NEW.reviewer_id);

  SELECT COALESCE(p.full_name, 'a reviewer') INTO v_author
  FROM public.profiles p WHERE p.id = NEW.reviewer_id;

  PERFORM private.create_notification(
    t.assigned_to,
    CASE NEW.decision WHEN 'Approved' THEN 'Task approved' ELSE 'Task changes requested' END,
    left(t.title, 120) || CASE NEW.decision
      WHEN 'Approved' THEN ' — approved by ' || v_author
      ELSE ' — changes requested by ' || v_author END,
    'info', 'tasks');

  PERFORM private.write_audit('TASK_REVIEWED', 'Task review: ' || NEW.decision::TEXT, 'task', NEW.task_id::TEXT,
    jsonb_build_object('decision', NEW.decision, 'reviewer', NEW.reviewer_id));

  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS task_reviews_apply ON public.task_reviews;
CREATE TRIGGER task_reviews_apply AFTER INSERT ON public.task_reviews
FOR EACH ROW EXECUTE FUNCTION private.apply_task_review();


-- ----------------------------------------------------------------------------
-- 5. Timeline + notifications on task changes
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION private.log_task_change() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE v_from TEXT;
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO public.task_events(task_id, event_type, title, actor_id)
    VALUES (NEW.id, 'created', 'Task created: ' || left(NEW.title, 200), (SELECT auth.uid()));
    PERFORM private.create_notification(NEW.assigned_to, 'New task assigned',
      left(NEW.title, 120), 'info', 'tasks');
    PERFORM private.write_audit('TASK_CREATED', 'Task created', 'task', NEW.id::TEXT,
      jsonb_build_object('matter', NEW.matter_id, 'assignee', NEW.assigned_to));
    RETURN NEW;
  END IF;

  IF NEW.assigned_to IS DISTINCT FROM OLD.assigned_to THEN
    SELECT COALESCE(p.full_name, '(former staff)') INTO v_from
    FROM public.profiles p WHERE p.id = OLD.assigned_to;
    INSERT INTO public.task_events(task_id, event_type, title, detail, actor_id)
    VALUES (NEW.id, 'assignment', 'Reassigned', 'From ' || COALESCE(v_from, '(former staff)'), (SELECT auth.uid()));
    PERFORM private.create_notification(NEW.assigned_to, 'Task assigned to you',
      left(NEW.title, 120), 'info', 'tasks');
    PERFORM private.write_audit('TASK_REASSIGNED', 'Task reassigned', 'task', NEW.id::TEXT,
      jsonb_build_object('from', OLD.assigned_to, 'to', NEW.assigned_to));
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    INSERT INTO public.task_events(task_id, event_type, title, detail, actor_id)
    VALUES (NEW.id, 'status', 'Status changed', OLD.status::TEXT || ' → ' || NEW.status::TEXT, (SELECT auth.uid()));
    IF NEW.status = 'In Review' THEN
      PERFORM private.create_notification(NEW.assigned_by, 'Task ready for review',
        left(NEW.title, 120), 'info', 'tasks');
    ELSIF NEW.status = 'Cancelled' THEN
      PERFORM private.create_notification(NEW.assigned_to, 'Task cancelled',
        left(NEW.title, 120), 'info', 'tasks');
    END IF;
    -- Completed is announced by apply_task_review() together with the
    -- decision text; a direct completion is done by the assignee themselves,
    -- so there is nobody else to notify.
    PERFORM private.write_audit('TASK_STATUS_CHANGED', 'Task ' || OLD.status || ' → ' || NEW.status,
      'task', NEW.id::TEXT, jsonb_build_object('old', OLD.status, 'new', NEW.status));
  END IF;

  IF NEW.due_date IS DISTINCT FROM OLD.due_date OR NEW.priority IS DISTINCT FROM OLD.priority THEN
    INSERT INTO public.task_events(task_id, event_type, title, actor_id)
    VALUES (NEW.id, 'planning', 'Due date or priority changed', (SELECT auth.uid()));
  END IF;

  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS tasks_log_change ON public.tasks;
CREATE TRIGGER tasks_log_change AFTER INSERT OR UPDATE ON public.tasks
FOR EACH ROW EXECUTE FUNCTION private.log_task_change();


-- ----------------------------------------------------------------------------
-- 6. Policies
-- ----------------------------------------------------------------------------
-- Select: assignee, creator, matter team (lawyers + paralegals), MP. Never
-- clients — tasks are internal work management.
DROP POLICY IF EXISTS tasks_select ON public.tasks;
CREATE POLICY tasks_select ON public.tasks FOR SELECT TO authenticated
  USING (assigned_to = (SELECT auth.uid())
      OR assigned_by = (SELECT auth.uid())
      OR (SELECT private.is_matter_team(matter_id))
      OR (SELECT private.is_admin()));

-- Create: matter lawyers on their matters, MP on any matter. The guard
-- stamps assigned_by and validates the assignee.
DROP POLICY IF EXISTS tasks_insert_managers ON public.tasks;
CREATE POLICY tasks_insert_managers ON public.tasks FOR INSERT TO authenticated
  WITH CHECK ((SELECT private.is_admin()) OR (SELECT private.is_matter_lawyer_team(matter_id)));

-- Update: the assignee (status only, enforced by the guard) and the managers.
DROP POLICY IF EXISTS tasks_update_assignee ON public.tasks;
CREATE POLICY tasks_update_assignee ON public.tasks FOR UPDATE TO authenticated
  USING (assigned_to = (SELECT auth.uid()))
  WITH CHECK (assigned_to = (SELECT auth.uid()));

DROP POLICY IF EXISTS tasks_update_managers ON public.tasks;
CREATE POLICY tasks_update_managers ON public.tasks FOR UPDATE TO authenticated
  USING ((SELECT private.is_admin())
      OR (SELECT private.is_matter_lawyer_team(matter_id))
      OR assigned_by = (SELECT auth.uid()))
  WITH CHECK ((SELECT private.is_admin())
      OR (SELECT private.is_matter_lawyer_team(matter_id))
      OR assigned_by = (SELECT auth.uid()));

-- No DELETE policy anywhere: tasks are cancelled, not deleted. History
-- (task_events, task_reviews) stays intact; matter deletion cascades.

-- task_reviews: visible exactly when the task is visible (same condition as
-- tasks_select, repeated here so the policy does not rely on nested RLS).
-- Insert is reviewer-only and capability-checked; there is no update or
-- delete policy — a recorded decision is immutable.
DROP POLICY IF EXISTS task_reviews_select ON public.task_reviews;
CREATE POLICY task_reviews_select ON public.task_reviews FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1 FROM public.tasks t
    WHERE t.id = task_id
      AND (t.assigned_to = (SELECT auth.uid())
        OR t.assigned_by = (SELECT auth.uid())
        OR (SELECT private.is_matter_team(t.matter_id))
        OR (SELECT private.is_admin()))
  ));

DROP POLICY IF EXISTS task_reviews_insert ON public.task_reviews;
CREATE POLICY task_reviews_insert ON public.task_reviews FOR INSERT TO authenticated
  WITH CHECK (
    reviewer_id = (SELECT auth.uid())
    AND EXISTS (
      SELECT 1 FROM public.tasks t
      WHERE t.id = task_id
        AND (t.assigned_by = (SELECT auth.uid())
          OR (SELECT private.is_matter_lawyer_team(t.matter_id))
          OR (SELECT private.is_admin()))
    )
  );

-- task_events: same visibility as the task. No insert policy — rows are
-- written by the SECURITY DEFINER triggers above only.
DROP POLICY IF EXISTS task_events_select ON public.task_events;
CREATE POLICY task_events_select ON public.task_events FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1 FROM public.tasks t
    WHERE t.id = task_id
      AND (t.assigned_to = (SELECT auth.uid())
        OR t.assigned_by = (SELECT auth.uid())
        OR (SELECT private.is_matter_team(t.matter_id))
        OR (SELECT private.is_admin()))
  ));


-- ----------------------------------------------------------------------------
-- 7. Realtime
-- ----------------------------------------------------------------------------
DO $$
DECLARE t TEXT;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_publication WHERE pubname = 'supabase_realtime') THEN
    RAISE NOTICE 'supabase_realtime publication not found — skipping realtime registration';
    RETURN;
  END IF;

  FOREACH t IN ARRAY ARRAY['tasks', 'task_reviews', 'task_events'] LOOP
    IF to_regclass('public.' || t) IS NULL THEN
      RAISE NOTICE 'public.% does not exist — skipped', t;
      CONTINUE;
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM pg_publication_tables
      WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = t
    ) THEN
      EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', t);
    END IF;
  END LOOP;
END $$;


-- ----------------------------------------------------------------------------
-- 8. Verify (read-only)
-- ----------------------------------------------------------------------------
DO $$
DECLARE
  v_status   TEXT;
  v_decision TEXT;
  v_tables   INTEGER;
  v_rls      INTEGER;
  v_policies INTEGER;
  v_pub      INTEGER;
BEGIN
  SELECT string_agg(e.enumlabel, ',' ORDER BY e.enumsortorder) INTO v_status
    FROM pg_enum e JOIN pg_type t ON t.oid = e.enumtypid WHERE t.typname = 'task_status';
  SELECT string_agg(e.enumlabel, ',' ORDER BY e.enumsortorder) INTO v_decision
    FROM pg_enum e JOIN pg_type t ON t.oid = e.enumtypid WHERE t.typname = 'review_decision';

  SELECT count(*) INTO v_tables FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relname IN ('tasks', 'task_reviews', 'task_events') AND c.relkind = 'r';
  SELECT count(*) INTO v_rls FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relname IN ('tasks', 'task_reviews', 'task_events') AND c.relrowsecurity;
  SELECT count(*) INTO v_policies FROM pg_policies
    WHERE schemaname = 'public' AND tablename IN ('tasks', 'task_reviews', 'task_events');
  SELECT count(*) INTO v_pub FROM pg_publication_tables
    WHERE pubname = 'supabase_realtime' AND schemaname = 'public'
      AND tablename IN ('tasks', 'task_reviews', 'task_events');

  RAISE NOTICE '--------------------------------------------------------------';
  RAISE NOTICE 'task_status values                      : %', v_status;
  RAISE NOTICE 'review_decision values                  : %', v_decision;
  RAISE NOTICE 'tables (want 3) / RLS on (want 3)       : % / %', v_tables, v_rls;
  RAISE NOTICE 'policies (want 7) / realtime (want 3)   : % / %', v_policies, v_pub;
  RAISE NOTICE '--------------------------------------------------------------';

  IF v_status IS DISTINCT FROM 'Open,In Progress,Blocked,In Review,Completed,Cancelled' THEN
    RAISE WARNING 'task_status enum values are wrong: %', v_status;
  END IF;
  IF v_decision IS DISTINCT FROM 'Approved,Changes Requested' THEN
    RAISE WARNING 'review_decision enum values are wrong: %', v_decision;
  END IF;
  IF v_tables <> 3 OR v_rls <> 3 OR v_policies < 7 THEN
    RAISE WARNING 'tasks surface incomplete: tables=% rls=% policies=%', v_tables, v_rls, v_policies;
  END IF;
  IF v_pub < 3 THEN
    RAISE NOTICE 'realtime: % of 3 tables published (publication may be absent locally)', v_pub;
  END IF;

  RAISE NOTICE 'tasks and reviews: OK';
END $$;


-- ############################################################################
-- ## 28/29  20261025_service_role_profile_write.sql
-- ############################################################################
-- ============================================================================
-- 20261025  service_role: write access to public.profiles
-- ============================================================================
-- admin-create-user sets profiles.role and profiles.must_change_password with
-- the service-role key. The live project never granted UPDATE on profiles to
-- service_role (20261018 added SELECT only), so that write died with
--
--   42501 permission denied for table profiles
--
-- and the function — correctly — rolled the new auth user back, making account
-- creation from the portal impossible. Reproduced live on 2026-10-13 with a
-- managing-partner session: "Failed to set up the account: permission denied
-- for table profiles", no orphan left behind.
--
-- Same class as 20261007 (content tables) and 20261011 (inquiries): the
-- project-level defaults do not cover every table, so the grants the edge
-- functions depend on must be explicit. SELECT is re-asserted for rebuilt
-- databases — the function reads the caller's profile before anything else.
GRANT SELECT, UPDATE ON public.profiles TO service_role;


-- ############################################################################
-- ## 29/29  20261026_single_lawyer_directory.sql
-- ############################################################################
-- ============================================================================
-- 20261026 — Single-lawyer directory
-- ============================================================================
-- The firm has one position: Lawyer. Two accounts remain in the public
-- directory — "Sample Lawyer" (the owner's own login) and Atty. Ernesto
-- "Boyet" Tabao. The six demo associates seeded by 20261001 are removed for
-- good: profile row, auth user, and every row that hangs off them.
--
-- Safe to run twice. The second run finds no demo accounts, prints a notice and
-- moves on; the position normalisation below is a plain idempotent UPDATE.
--
-- What happens to dependent rows
--   CASCADE   notifications, appointments, matter_members, profile_practice_areas,
--             audit_logs
--                -> deleted together with the account
--   SET NULL  matters.assigned_to/client_id, matter_events.actor_id,
--             corporate_clients.added_by, articles.author_profile_id,
--             seminar_events.speaker_profile_id, inquiries.assigned_to /
--             requested_lawyer_id, seminar_email_log.sent_by, tasks.assigned_by
--                -> row kept, reference cleared
--   RESTRICT  documents.uploaded_by, matter_notes.author_id,
--             inquiry_messages.author_id, tasks.assigned_to,
--             task_reviews.reviewer_id
--                -> re-anchored to the surviving managing account, otherwise
--                   Postgres refuses the delete outright
--
-- The RESTRICT re-anchor is the only place that rewrites data. It touches rows
-- only where a demo account is the recorded author/assignee, and it prints the
-- count for each table so the effect is visible in the SQL editor output.
-- ============================================================================

DO $cleanup$
DECLARE
  -- Identified by email, not by id: ids differ between projects, emails are
  -- what the 20261001 seed created and what the owner's live project holds.
  demo_emails TEXT[] := ARRAY[
    'mc.santos@westwoodlaw.ph',
    'bj.reyes@westwoodlaw.ph',
    'l.delacruz@westwoodlaw.ph',
    'cg.torres@westwoodlaw.ph',
    'si.mendoza@westwoodlaw.ph',
    'ma.villanueva@westwoodlaw.ph'
  ];
  victims UUID[];
  anchor  UUID;
  moved   BIGINT;
BEGIN
  SELECT array_agg(p.id) INTO victims
  FROM public.profiles p
  WHERE lower(p.email) = ANY (demo_emails);

  IF victims IS NULL THEN
    RAISE NOTICE 'No demo lawyer accounts left — nothing to delete.';
    RETURN;
  END IF;

  -- The account that inherits RESTRICT-bound rows: Atty. Tabao while he is
  -- still around, otherwise whoever survives.
  SELECT p.id INTO anchor
  FROM public.profiles p
  WHERE p.role = 'lawyer'
    AND lower(p.email) = 'atty.boyet@westwoodlaw.ph'
    AND NOT (p.id = ANY (victims));

  IF anchor IS NULL THEN
    SELECT p.id INTO anchor
    FROM public.profiles p
    WHERE p.role = 'lawyer' AND NOT (p.id = ANY (victims))
    ORDER BY p.display_order NULLS LAST, p.created_at
    LIMIT 1;
  END IF;

  IF anchor IS NULL THEN
    RAISE EXCEPTION
      'No surviving lawyer to re-anchor documents, notes, messages and tasks to — aborting before deleting anything.';
  END IF;

  -- --------------------------------------------------------------------------
  -- 1. Clear the RESTRICT references. Each table is guarded by to_regclass()
  --    because a project that never ran the migration owning it has no table,
  --    and a missing table must not stop the cleanup.
  -- --------------------------------------------------------------------------
  IF to_regclass('public.documents') IS NOT NULL THEN
    EXECUTE 'UPDATE public.documents SET uploaded_by = $1 WHERE uploaded_by = ANY ($2)'
      USING anchor, victims;
    GET DIAGNOSTICS moved = ROW_COUNT;
    RAISE NOTICE 'documents re-anchored: %', moved;
  END IF;

  IF to_regclass('public.matter_notes') IS NOT NULL THEN
    EXECUTE 'UPDATE public.matter_notes SET author_id = $1 WHERE author_id = ANY ($2)'
      USING anchor, victims;
    GET DIAGNOSTICS moved = ROW_COUNT;
    RAISE NOTICE 'matter notes re-anchored: %', moved;
  END IF;

  IF to_regclass('public.inquiry_messages') IS NOT NULL THEN
    EXECUTE 'UPDATE public.inquiry_messages SET author_id = $1 WHERE author_id = ANY ($2)'
      USING anchor, victims;
    GET DIAGNOSTICS moved = ROW_COUNT;
    RAISE NOTICE 'inquiry messages re-anchored: %', moved;
  END IF;

  IF to_regclass('public.tasks') IS NOT NULL THEN
    EXECUTE 'UPDATE public.tasks SET assigned_to = $1 WHERE assigned_to = ANY ($2)'
      USING anchor, victims;
    GET DIAGNOSTICS moved = ROW_COUNT;
    RAISE NOTICE 'tasks re-anchored: %', moved;
  END IF;

  IF to_regclass('public.task_reviews') IS NOT NULL THEN
    EXECUTE 'UPDATE public.task_reviews SET reviewer_id = $1 WHERE reviewer_id = ANY ($2)'
      USING anchor, victims;
    GET DIAGNOSTICS moved = ROW_COUNT;
    RAISE NOTICE 'task reviews re-anchored: %', moved;
  END IF;

  -- --------------------------------------------------------------------------
  -- 2. Delete the accounts. auth.users is the root: profiles.id cascades from
  --    it, and so does everything that cascades from profiles.
  -- --------------------------------------------------------------------------
  DELETE FROM auth.users u WHERE u.id = ANY (victims);
  GET DIAGNOSTICS moved = ROW_COUNT;
  RAISE NOTICE 'auth users deleted: %', moved;

  -- Belt and braces: a project whose profiles.id never got the cascade would
  -- otherwise keep an orphan row that still shows up in public_lawyers.
  DELETE FROM public.profiles p WHERE p.id = ANY (victims);
  GET DIAGNOSTICS moved = ROW_COUNT;
  RAISE NOTICE 'orphan profiles deleted: %', moved;
END
$cleanup$;

-- ----------------------------------------------------------------------------
-- 3. One position for the whole firm.
-- ----------------------------------------------------------------------------
-- The directory, the admin "Position at the Firm" dropdown and the profile
-- editor all read this column. Nulls are included: "Sample Lawyer" was seeded
-- without a position and would otherwise keep falling back to the literal
-- "Lawyer" in the components instead of being stored as one.
UPDATE public.profiles
SET position = 'Lawyer',
    updated_at = NOW()
WHERE role = 'lawyer'
  AND position IS DISTINCT FROM 'Lawyer';

-- ----------------------------------------------------------------------------
-- 4. Verification — read the grid.
-- ----------------------------------------------------------------------------
-- expect: 2 lawyers, 2 directory rows, one distinct position ("Lawyer"), and
-- zero rows for any of the six demo addresses.
SELECT 'lawyers'                 AS metric, count(*)::TEXT AS value
FROM public.profiles WHERE role = 'lawyer'
UNION ALL
SELECT 'public_lawyers rows',    count(*)::TEXT
FROM public.public_lawyers
UNION ALL
SELECT 'distinct positions',     COALESCE(string_agg(DISTINCT position, ', '), '(none)')
FROM public.profiles WHERE role = 'lawyer'
UNION ALL
SELECT 'demo accounts remaining', count(*)::TEXT
FROM public.profiles
WHERE lower(email) IN (
  'mc.santos@westwoodlaw.ph', 'bj.reyes@westwoodlaw.ph', 'l.delacruz@westwoodlaw.ph',
  'cg.torres@westwoodlaw.ph', 'si.mendoza@westwoodlaw.ph', 'ma.villanueva@westwoodlaw.ph'
);


-- ############################################################################
